/* ------------------------- the endpoint contract -------------------------- */
/* Frozen by docs/TRACE-PLAN.md so Lanes A-D never negotiate it. ADDED here,   */
/* not ported — the donor package has no terminal concept at all.              */

export interface Point {
  x: number;
  y: number;
}

/**
 * Flow tangent at a terminal — the direction the arrow glyph points, i.e.
 * the direction data travels THROUGH that point. Same vocabulary as the
 * elbow router's `ElbowSide` ("top" = flow upward).
 *
 * WHY there are four of these and not eight: a port's (face, polarity) pair
 * maps onto a flow tangent exactly 2-to-1. An output emits along its face
 * normal (`tangent = face`); an input receives against it
 * (`tangent = opposite(face)`). So input-on-top-face and
 * output-on-bottom-face draw as the identical glyph — a circle with a
 * downward arrow. Zach's own correction: "really 4 options not 8 because
 * top input is the same as bottom output." `TraceTerminal` therefore takes
 * NO polarity prop at all; which end is which comes from the `from`/`to`
 * slot (the arrowhead rides the `to` end), never from the glyph.
 */
export type TraceDir = "top" | "right" | "bottom" | "left";

export const TRACE_DIRS = ["top", "right", "bottom", "left"] as const;

export const OPPOSITE_DIR: Record<TraceDir, TraceDir> = {
  top: "bottom",
  right: "left",
  bottom: "top",
  left: "right",
};

export interface TraceTerminalSpec {
  x: number;
  y: number;
  dir: TraceDir;
}

/** Declared in P1 so Lanes B/C widen nothing later; P2 implements
 * `straight`/`slanted`/`curved`, P3 `elbow`. */
export type TraceRouting = "straight" | "slanted" | "curved" | "elbow";

/**
 * What a cable draws as when nobody says.
 *
 * WHY: "by default elbow arrows should always be used. never straight
 * arrows" — Zach, 2026-09-19, looking at `Pasted image 20260919114952.png`
 * (Source → A → B → Sink drawn as diagonal chords). The other three
 * routings remain SELECTABLE — `straight` is still what a caller gets by
 * asking for it, and `TraceRouting.stories.tsx` still draws all four side
 * by side — but none of them is ever what a caller gets by saying nothing.
 *
 * It lives HERE, beside the union it names, and not in `trace.tsx`, because
 * three unrelated seams have to agree on it: the `Trace` component's own
 * prop default, `WireLayer`'s resolution (which must know the answer BEFORE
 * it decides whether to collect keep-outs), and the tldraw host's overlay.
 * A default spelled three times is how "never straight" becomes true in two
 * hosts and false in the third.
 */
export const DEFAULT_TRACE_ROUTING: TraceRouting = "elbow";

/**
 * The router's side for each end, from the frozen contract:
 *
 *   side(from) = from.dir                 // the wire LEAVES along the flow
 *   side(to)   = OPPOSITE_DIR[to.dir]     // it ARRIVES travelling to.dir,
 *                                         // so its free space is behind it
 *
 * Matching the elbow router's own doc ("an output port leaves 'right', an
 * input enters 'left'"): output-right => side `right`; input-left => flow
 * `right`, side `left`.
 */
export function traceSideOf(terminal: TraceTerminalSpec, end: "from" | "to"): TraceDir {
  return end === "from" ? terminal.dir : OPPOSITE_DIR[terminal.dir];
}

/** The unit screen-space vector a `TraceDir` points along. SVG's y grows
 * DOWNWARD, so "top" is -y. */
export const DIR_VECTOR: Record<TraceDir, Point> = {
  top: { x: 0, y: -1 },
  right: { x: 1, y: 0 },
  bottom: { x: 0, y: 1 },
  left: { x: -1, y: 0 },
};

/** Clockwise degrees to rotate a +x-pointing glyph so it points `dir`.
 * (SVG `rotate()` is clockwise-positive precisely because y grows down.) */
export const DIR_ROTATION: Record<TraceDir, number> = {
  right: 0,
  bottom: 90,
  left: 180,
  top: 270,
};

/* ------------------------------- geometry -------------------------------- */

export function polylineLength(points: readonly Point[]): number {
  let length = 0;
  for (let index = 1; index < points.length; index += 1) {
    length += Math.hypot(points[index].x - points[index - 1].x, points[index].y - points[index - 1].y);
  }
  return length;
}

/**
 * Points -> an SVG `d`. SERIALIZATION, not derivation: `Trace` still never
 * invents a point (`trace.tsx`'s promise, and `ARCHITECTURE.md`'s) — a
 * caller that already HAS the vertices uses this instead of hand-rolling
 * string concatenation at every call site. P2's curved routing does not use
 * it; that path is cubic.
 */
export function polylinePath(points: readonly Point[]): string {
  if (points.length === 0) return "";
  return points.map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`).join(" ");
}

/** The point a fraction `t` of the arc length along the polyline. */
export function pointAtFraction(points: readonly Point[], t: number): Point {
  if (points.length === 0) return { x: 0, y: 0 };
  if (points.length === 1) return { x: points[0].x, y: points[0].y };
  const total = polylineLength(points);
  let target = Math.min(1, Math.max(0, t)) * total;
  for (let index = 1; index < points.length; index += 1) {
    const a = points[index - 1];
    const b = points[index];
    const segment = Math.hypot(b.x - a.x, b.y - a.y);
    if (target <= segment || index === points.length - 1) {
      const u = segment === 0 ? 0 : Math.min(1, target / segment);
      return { x: a.x + (b.x - a.x) * u, y: a.y + (b.y - a.y) * u };
    }
    target -= segment;
  }
  const last = points[points.length - 1];
  return { x: last.x, y: last.y };
}

/**
 * The arc-length fraction of the polyline point nearest `p` — where a
 * dragged label lands. Host-owned drag math (`labelPosition` is the
 * number a host WRITES back after a drag), kept here because it is pure.
 */
export function fractionNearest(points: readonly Point[], p: Point): number {
  if (points.length < 2) return 0.5;
  const total = polylineLength(points);
  if (total === 0) return 0.5;
  let best = { distance: Number.POSITIVE_INFINITY, length: 0 };
  let walked = 0;
  for (let index = 1; index < points.length; index += 1) {
    const a = points[index - 1];
    const b = points[index];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const segment = Math.hypot(dx, dy);
    const u = segment === 0 ? 0 : Math.min(1, Math.max(0, ((p.x - a.x) * dx + (p.y - a.y) * dy) / (segment * segment)));
    const qx = a.x + dx * u;
    const qy = a.y + dy * u;
    const distance = Math.hypot(p.x - qx, p.y - qy);
    if (distance < best.distance) best = { distance, length: walked + segment * u };
    walked += segment;
  }
  return best.length / total;
}

/* --------------------------- path addressing (D4) -------------------------- */
/*
 * One 1-D coordinate scheme for anything that rides a trace's polyline —
 * `TraceBadge`'s pill (widened, not replaced) and the new `TraceMark`
 * (./traceMark.tsx). Ruling 4, verbatim: "Interesting idea for marks on
 * cable getting 1d coordinate... we already support this for the
 * placement of the pill... if there is a pill already we don't likely
 * want to render it directly on the pill." Two mature libraries converged
 * on the same shape independently — maxGraph's label geometry
 * (`x ∈ [-1..1]` + orthogonal offset) and JointJS's `distance` (px,
 * percent, or negative-from-the-end) + perpendicular `offset` — which is
 * the argument FOR unifying rather than inventing a third vocabulary.
 *
 * `PathAddress` is deliberately two cases, not three: a plain fraction
 * (the currency `TraceBadge` already speaks) and `{px}` (JointJS's own
 * arc-length-pixels case). There is no percent-string case — a fraction
 * already IS a percent (`0.2` === `20%`), so adding `"20%"` would just be
 * a second spelling of the same number.
 */
export type PathAddress = number | { px: number };

/**
 * `PathAddress` -> a resolved arc-length fraction, clamped to `[0, 1]` —
 * NOT `clampLabelPosition`'s 0.05..0.95 band. That band exists so a
 * *label* never sits ON a terminal and reads as part of it
 * (`LABEL_POSITION_MIN`/`MAX`'s own doc, above); a `TraceMark` pinned to
 * the BROKEN end of a dangling edge (`{px: -24}`) needs exactly the
 * opposite — the whole `[0, 1]` range, end included. Callers that DO want
 * the label band (`TraceBadge`) apply `clampLabelPosition` themselves,
 * after this function, the same order `TraceBadge` already resolved `t`
 * before clamping it.
 *
 * Two provenances, and they are NOT the same claim:
 *
 * - `{px: n}` with `n < 0` measuring from the path's END is
 *   BEHAVIOUR-DERIVED from JointJS's own `Path.pointAtLength` negative
 *   branch (dist `joint.js:7802-7808` — the validation-stack oracle
 *   session ran it live: `distance:-20` landed ~28px from the target end).
 *   MPL-2.0; reimplemented from the observed behaviour, no JointJS source
 *   copied.
 * - Negative FRACTIONS resolving the same way (`f < 0` -> `t = 1 + f`) are
 *   OURS, built deliberately for symmetry — NOT a port. The same oracle
 *   session ran JointJS's own PERCENT form (`distance: '-20%'`) and found
 *   it does the opposite: it clamps negative percentages to the SOURCE
 *   end instead of counting from the target end (`joint.js:8047-8068`).
 *   So "negative counts from the end" is true for JointJS's px case and
 *   false for its own percent case — we chose the symmetric interpretation
 *   deliberately rather than inheriting either one by "analogy". `-0`
 *   behaves as `0` (`-0 < 0` is `false` in JS) — pass the literal `1` for
 *   the exact end.
 */
export function resolvePathAddress(points: readonly Point[], address: PathAddress): number {
  if (typeof address === "number") {
    const t = address < 0 ? 1 + address : address;
    return Math.min(1, Math.max(0, t));
  }
  const total = polylineLength(points);
  if (!(total > 0) || !Number.isFinite(address.px)) return 0;
  const t = address.px < 0 ? 1 + address.px / total : address.px / total;
  return Math.min(1, Math.max(0, t));
}

/**
 * The unit tangent (flow direction) of the polyline at arc-length fraction
 * `t` — what `TraceMark` rotates its perpendicular `offsetPx` against so a
 * mark rides beside the line rather than floating at a fixed screen angle.
 * Falls back to the first non-degenerate segment (then to a bare
 * rightward unit vector) when the chosen segment has zero length — a
 * repeated point in `points` must never divide by zero.
 */
export function tangentAtFraction(points: readonly Point[], t: number): Point {
  if (points.length < 2) return { x: 1, y: 0 };
  const total = polylineLength(points);
  let target = Math.min(1, Math.max(0, t)) * total;
  for (let index = 1; index < points.length; index += 1) {
    const a = points[index - 1];
    const b = points[index];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const segment = Math.hypot(dx, dy);
    if (target <= segment || index === points.length - 1) {
      if (segment > 0) return { x: dx / segment, y: dy / segment };
      break;
    }
    target -= segment;
  }
  for (let index = 1; index < points.length; index += 1) {
    const a = points[index - 1];
    const b = points[index];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const segment = Math.hypot(dx, dy);
    if (segment > 0) return { x: dx / segment, y: dy / segment };
  }
  return { x: 1, y: 0 };
}

export interface PathPlacement {
  t: number;
  widthPx: number;
  /** Never moved — the pill's own slot, when one is already parked here. */
  pinned?: boolean;
}

/**
 * OURS, AD HOC — not a port. The justification is the gap itself: the
 * validation-stack oracle session ran JointJS's own `ToolsView`
 * positioning live and found ZERO collision avoidance — two
 * `distance:'50%'` tools landed at the IDENTICAL pixel
 * (`getBoundingClientRect` equal to the last digit; z-order was DOM
 * append order, `joint.js:37752-37820`). Nothing to port; this is
 * written fresh.
 *
 * Pinned placements never move. Every unpinned placement is nudged, in
 * the order given, to the nearest arc-length position that clears every
 * placement resolved so far (pinned ones plus earlier unpinned ones) by
 * at least `gapPx` of clear path, measured edge-to-edge in pixels along
 * `lengthPx`. Ties between "push right" and "push left" favour whichever
 * is closer to the placement's own requested `t`; a genuine tie favours
 * the right (higher-`t`) side, arbitrarily but deterministically.
 *
 * Returns one resolved fraction per input placement, in input order,
 * each clamped to `[0, 1]`.
 */
export function separateAlongPath(lengthPx: number, placements: readonly PathPlacement[], gapPx = 8): number[] {
  const length = Number.isFinite(lengthPx) && lengthPx > 0 ? lengthPx : 0;
  const half = (p: PathPlacement) => Math.max(0, p.widthPx) / 2;
  const toPx = (p: PathPlacement) => Math.min(1, Math.max(0, p.t)) * length;

  interface Interval {
    lo: number;
    hi: number;
  }
  const settled: Interval[] = [];
  const resultPx: number[] = new Array(placements.length).fill(0);

  // Pinned placements are fixed obstacles, resolved first regardless of
  // their position in the input array — an unpinned placement earlier in
  // the array must still yield to a pinned one that appears later.
  placements.forEach((p, index) => {
    if (!p.pinned) return;
    const pos = toPx(p);
    resultPx[index] = pos;
    settled.push({ lo: pos - half(p), hi: pos + half(p) });
  });

  placements.forEach((p, index) => {
    if (p.pinned) return;
    let pos = toPx(p);
    const h = half(p);
    // Bounded re-check: moving to clear one interval can land inside
    // another. `settled.length + 1` passes is always enough to walk clear
    // of every existing interval once, because each pass resolves at
    // least the interval(s) it was pushed to avoid.
    for (let pass = 0; pass <= settled.length; pass += 1) {
      const overlapping = settled.filter((iv) => pos - h - gapPx < iv.hi && pos + h + gapPx > iv.lo);
      if (overlapping.length === 0) break;
      const rightEdge = Math.max(...overlapping.map((iv) => iv.hi)) + gapPx + h;
      const leftEdge = Math.min(...overlapping.map((iv) => iv.lo)) - gapPx - h;
      const right = Math.min(length, rightEdge);
      const left = Math.max(0, leftEdge);
      const distRight = Math.abs(right - pos);
      const distLeft = Math.abs(left - pos);
      pos = distLeft < distRight ? left : right;
    }
    pos = Math.min(length, Math.max(0, pos));
    resultPx[index] = pos;
    settled.push({ lo: pos - h, hi: pos + h });
  });

  return resultPx.map((pos) => (length > 0 ? Math.min(1, Math.max(0, pos / length)) : 0));
}

/* ------------------------------ label position ---------------------------- */

/** Kept off the terminals — a label sitting exactly on a port reads as
 * part of it, not a fact about the trace. Same bounds as SystemSketch's
 * own `PILL_POSITION_MIN`/`MAX` (`connectionModel.ts`). */
export const LABEL_POSITION_MIN = 0.05;
export const LABEL_POSITION_MAX = 0.95;
export const LABEL_POSITION_DEFAULT = 0.5;

export function clampLabelPosition(t: number): number {
  return Math.min(LABEL_POSITION_MAX, Math.max(LABEL_POSITION_MIN, t));
}

/* ------------------------------ dash arrays ------------------------------ */

/**
 * `async`: equal rests between small packet marks. SVG alternates paint
 * and gaps, so this reads as a 56-unit carrier, 4-unit micro-gap, 10-unit
 * packet, then another 4-unit micro-gap before the cadence repeats. Butt
 * caps keep the tiny gaps legible instead of visually closing them with
 * round end caps. Numbers unchanged from SystemSketch's own
 * `ASYNC_PACKET_DASHARRAY` — this is the board's visual grammar, not a
 * library's, and porting it is a rename of ownership, not a rewrite.
 */
export const ASYNC_CARRIER_PX = 56;
export const ASYNC_PACKET_GAP_PX = 4;
export const ASYNC_PACKET_PX = 10;
export const ASYNC_PACKET_DASHARRAY = `${ASYNC_CARRIER_PX} ${ASYNC_PACKET_GAP_PX} ${ASYNC_PACKET_PX} ${ASYNC_PACKET_GAP_PX}`;
export const ASYNC_CADENCE_PX = ASYNC_CARRIER_PX + ASYNC_PACKET_GAP_PX * 2 + ASYNC_PACKET_PX;

/**
 * Below one full cadence there is not enough path to reach both
 * micro-gaps, so phase just that short run to centre one complete
 * gap-packet-gap mark. The cadence itself never changes.
 */
export function asyncDashOffsetForLength(lengthPx: number): number {
  if (!Number.isFinite(lengthPx) || lengthPx >= ASYNC_CADENCE_PX) return 0;
  const packetMark = ASYNC_PACKET_GAP_PX * 2 + ASYNC_PACKET_PX;
  const markStart = Math.max(0, (Math.max(0, lengthPx) - packetMark) / 2);
  return ASYNC_CARRIER_PX - markStart;
}

/**
 * `data`, opt-in `animated`: React Flow's own homepage marching-ants line
 * (`stroke-dasharray: 5px`). Opt-in, never a default — the 2026-09-14
 * lesson `connectionPresentation.ts` already recorded: on-by-default
 * proved too loud.
 */
export const DATA_MARCH_DASH_PX = 5;
export const DATA_MARCH_DASHARRAY = `${DATA_MARCH_DASH_PX}`;
/**
 * The keyframe's own from->to span. CSS can't reference this constant
 * directly — `globals.css`'s `@keyframes bbox-trace-march` hardcodes the
 * same `10`/`0` literally — so this exists as the pinned value a test
 * checks the CSS against, catching drift if `DATA_MARCH_DASH_PX` ever
 * changes without the keyframes changing to match. `Trace.stories.tsx`'s
 * `Styles` play function is that test.
 */
export const DATA_MARCH_DASHOFFSET_PX = DATA_MARCH_DASH_PX * 2;
/** The class `globals.css` hangs the keyframes on. `traceStrokeStyle`
 * returns only this NAME — never the keyframes themselves — so every Trace
 * on a page marches at one speed off one definition. */
export const DATA_MARCH_CLASS = "bbox-trace-march";

/** The dot: a zero-length dash with a round cap paints a disc of the
 * stroke width. */
export const DELAY_DOT_PX = 0.1;
export const DELAY_DOT_GAP_PX = 6;

/** `pathLength` the split paths are normalised to, so dashes are set in
 * path units rather than pixels — the split stays correct at any zoom. */
export const PATH_LENGTH_UNITS = 1000;

export interface SplitDashArrays {
  /** Solid up to the label, then a gap that outlasts the path. */
  before: string;
  /** A gap up to the label, then dotted to the end, then a gap that outlasts the path. */
  after: string;
}

/**
 * Hard ceiling on how many dot/gap pairs `splitDashArrays` ever builds.
 *
 * DEVIATION found by adversarial review (2026-09-15): the first version
 * of this function filled the dotted run with an open-ended
 * `while (covered < PATH_LENGTH_UNITS) { ...; covered += dot + dotGap }`
 * loop. For an ordinary `lengthPx` (tens to thousands of real pixels)
 * that terminates in well under 200 iterations — but nothing validated
 * `lengthPx`, and a pathologically large value (`Infinity`,
 * `Number.MAX_VALUE`, or anything astronomically large) drives `unit`
 * toward 0, so `dot`/`dotGap` underflow toward 0 and `covered` stops
 * advancing at all — a genuine infinite loop that crashed with
 * `RangeError: Invalid array length` once the array hit JS's engine
 * limit, found live by running exactly that input. A closed-form dot
 * COUNT, computed once and capped, replaces the loop outright: no input,
 * however degenerate, can make this function run unbounded work again.
 * The cap itself is generous for anything real — a normal `delayed`
 * trace's dotted run is under 200 dots even at large pixel lengths.
 */
const MAX_DELAY_DOTS = 2000;

/**
 * Two dash arrays that, drawn on the same path with `pathLength=1000`,
 * paint solid before the split point and dots after it. Each pattern ends
 * with a gap of a full path so SVG's repeating never spills one style
 * into the other's run.
 */
export function splitDashArrays(lengthPx: number, t: number): SplitDashArrays {
  const fraction = clampLabelPosition(t);
  const unit = Number.isFinite(lengthPx) && lengthPx > 0 ? PATH_LENGTH_UNITS / lengthPx : 1;
  const dot = DELAY_DOT_PX * unit;
  const dotGap = DELAY_DOT_GAP_PX * unit;
  const splitAt = fraction * PATH_LENGTH_UNITS;

  const before: number[] = [splitAt, PATH_LENGTH_UNITS];

  const pairSpan = dot + dotGap;
  const remaining = PATH_LENGTH_UNITS - splitAt;
  const dotCount = pairSpan > 0 && Number.isFinite(pairSpan)
    ? Math.min(MAX_DELAY_DOTS, Math.ceil(remaining / pairSpan))
    : 0;

  const after: number[] = [0, splitAt];
  for (let i = 0; i < dotCount; i += 1) after.push(dot, dotGap);
  after.push(0, PATH_LENGTH_UNITS);

  const round = (value: number) => Number(value.toFixed(3));
  return {
    before: before.map(round).join(" "),
    after: after.map(round).join(" "),
  };
}

// src/components/wiring.ts — `WireLayer`'s paint vocabulary: what a wire
// LOOKS like between two rendered dots, plus how N wires sharing one
// endpoint pair fan apart so they are visibly N (`fanWires`, D-B3).
//
// This file used to be a third thing as well: the connection RECORD, with
// its own derivation (`wiredPortKeys`). That role is absorbed — the record
// is `scene.ts`'s `SceneEdge` (source/target/sourceHandle/targetHandle,
// React Flow's own vocabulary), the derivation is `scene.ts`'s
// `wiredPorts`, and the item-state mapping moved to the adapter
// (`sceneWires.ts`'s `withWiredState`). Deleted here, deliberately:
// `wireEndKey`, `wiredPortKeys`, `withWiredState` — so there is exactly
// ONE model and this module cannot quietly grow back into a second one.
//
// What remains is view-kit only, and this file still imports NOTHING from
// `src/scene/` — `Wire` is a paint instruction a host DERIVES from a scene
// (`sceneWires.ts`), never a record a host authors as its source of truth.
// `WireLayer` (a component) imports this module, and the components-never-
// import-the-scene wall holds precisely because the scene types stay out
// of here, even transitively.
//
// The permission-free stance is unchanged (Zach, 2026-09-17: "draw as many
// wires as you want... even multiple wires between the same two ports") —
// nothing here validates; everything is derivation over whatever list it
// is handed.

import type { TraceMarkerEnd, TraceRouting, TraceVariant } from "./trace.layout";

/* ------------------------------------------------------------------ */
/* The paint instruction                                               */
/* ------------------------------------------------------------------ */

export interface WireEnd {
  blockId: string;
  portId: string;
}

export interface Wire {
  id: string;
  /** The initiating end — an arrowhead, when a wire opts into one
   *  (`markerEnd: "arrow"`), points AT `to`; the default draws none
   *  (`DEFAULT_TRACE_MARKER_END`). A scene edge's source/target map to
   *  from/to with the direction preserved (`sceneWires.ts`). */
  from: WireEnd;
  to: WireEnd;
  /** Default `"data"`; the async gallery passes `"async"` (D-B6's reading
   *  of the donor's "new wires default to async", `asyncRegionModel.ts`). */
  variant?: TraceVariant;
  /** Default is `Trace`'s own default (`"curved"`). */
  routing?: TraceRouting;
  /** Default is `Trace`'s own default (`DEFAULT_TRACE_MARKER_END`, `"none"`). */
  markerEnd?: TraceMarkerEnd;
  color?: string;
  /**
   * Block/region/arm ids this wire is ALLOWED to pass through — the
   * containers its two ends live inside (a host derives it from
   * `ancestorsOf`; `sceneWires.ts`). `WireLayer` treats every other
   * measured box as a keep-out when `routing === "elbow"`: that is the
   * whole of "cables that do not flow through a region must route around
   * it — bypass above or below" (docs/CONTROL-FLOW-PLAN.md, lane D).
   */
  through?: readonly string[];
  /** Text of a pill riding the wire (`TraceBadge`): `z⁻¹` on a delayed
   *  cable, `mut` on an effect cable. Absent = no pill. */
  badge?: string;
}

/* ------------------------------------------------------------------ */
/* Keep-outs (lane D) — CONTRACT STUB, frozen by wiring.test.ts         */
/* ------------------------------------------------------------------ */

/** A measured box a wire may have to avoid, keyed by the id that stamped it
 *  (`data-block-id`, `data-region-id` or `data-arm-id`). Container-local px. */
export interface KeepOutRect {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

/**
 * The obstacles ONE wire routes around: every rect except its own two
 * endpoint blocks and everything in `through`. Input order, always a new
 * array, `{x, y, w, h}` only (an `ElbowRect`) — the endpoint boxes travel
 * separately as the router's `fromBox`/`toBox`.
 */
export function keepOutsFor(
  wire: Pick<Wire, "from" | "to" | "through">,
  rects: readonly KeepOutRect[],
): { x: number; y: number; w: number; h: number }[] {
  // WHY the exclusion set is exactly "my two ends plus `through`", and
  // nothing cleverer: bypass means AVOID EVERYTHING EXCEPT what I am part
  // of. A cable into a block sitting in a branch's arm may enter that
  // region's frame and that one arm — both are in `through`, because both
  // are ancestors of an end — and it may not enter a SIBLING arm, which is
  // not. That is DRAKON's "an arm is entered only from the shared area"
  // made mechanical: the rule is a set membership over measured boxes, not
  // a special case per container kind, so a region, an arm and a plain
  // block are all treated identically here and nothing has to know which
  // is which. The tempting alternative — "skip any rect that CONTAINS an
  // endpoint" — reads equivalent and is not: a sibling arm that happens to
  // overlap an endpoint's box geometrically would be silently entered,
  // and a container the wire genuinely crosses but whose measured rect has
  // not settled yet would be silently kept out.
  const mine = new Set<string>([wire.from.blockId, wire.to.blockId, ...(wire.through ?? [])]);
  // A NEW array of NEW `{x, y, w, h}` objects, in `rects`' own order: the
  // id is the collector's bookkeeping, not the router's vocabulary
  // (`ElbowRoutingObstacle` has no id), and a caller that got the input
  // array back could mutate one layer's measurements from another's.
  return rects
    .filter((rect) => !mine.has(rect.id))
    .map(({ x, y, w, h }) => ({ x, y, w, h }));
}

/* ------------------------------------------------------------------ */
/* Duplicate fan (D-B3)                                                */
/* ------------------------------------------------------------------ */

/**
 * Perpendicular spread between duplicate wires sharing one endpoint pair.
 *
 * NO LONGER APPLIED TO PAINT (2026-09-19). Zach, looking at three cables
 * leaving one `pose` dot at three stacked offsets (`Pasted image
 * 20260919115137.png`): "very bad. edges should always leave from the center
 * of the port… The port only should have 1 connection point in the center.
 * Instead you should show the producer circle that has the number for the
 * number of arrows intersecting at that port."
 *
 * So the FACT this number expressed — "there are N cables here" — survives;
 * only its expression moved, from geometry to a count badge on the dot.
 * `fanWires` below is the grouping that count is derived from, which is why
 * it is still here and still tested rather than deleted: the producer count
 * and any future "which duplicate am I" affordance must agree about what
 * counts as a duplicate, and one function is how they do.
 *
 * The number itself is kept at its measured value so the two halves of the
 * story stay legible in a diff; nothing reads it any more.
 */
export const DUPLICATE_FAN_PX = 14;

/** Unordered: a wire and a same-pair wire drawn the other way (`a→b` beside
 *  `b→a`) still fan against each other — the visible fact is "N wires
 *  between these two dots", not which end either one calls `from`. The same
 *  rule the scene kit's `duplicateEdges` lint applies, restated over the
 *  paint vocabulary, so the lint and the drawing can never disagree about
 *  what counts as a duplicate. */
function unorderedPairKey(a: WireEnd, b: WireEnd): string {
  const ka = `${a.blockId}/${a.portId}`;
  const kb = `${b.blockId}/${b.portId}`;
  return ka <= kb ? `${ka}|${kb}` : `${kb}|${ka}`;
}

export interface WireFan {
  /** This wire's 0-based rank among the others sharing its endpoint pair. */
  index: number;
  /** How many wires share this endpoint pair, this one included. */
  count: number;
  /** The `curve` offset `Trace` already understands (`trace.routing.ts`'s
   *  `TraceCurve`) — `{dx: 0, dy: ...}` per plan §5, centred on 0 so a lone
   *  wire between a pair fans by nothing at all. */
  offset: { dx: number; dy: number };
}

/** One `WireFan` per wire, in `wires`' own order. `index`/`count` are the
 *  live half — "this is cable 2 of 3 between these two dots", which is what
 *  a producer-count badge reports; `offset` is no longer applied to paint
 *  (see `DUPLICATE_FAN_PX`). */
export function fanWires(wires: readonly Wire[]): WireFan[] {
  const idsByPair = new Map<string, string[]>();
  for (const wire of wires) {
    const key = unorderedPairKey(wire.from, wire.to);
    const ids = idsByPair.get(key);
    if (ids) ids.push(wire.id);
    else idsByPair.set(key, [wire.id]);
  }
  const rankById = new Map<string, { index: number; count: number }>();
  for (const ids of idsByPair.values()) {
    ids.forEach((id, index) => rankById.set(id, { index, count: ids.length }));
  }
  return wires.map((wire) => {
    const rank = rankById.get(wire.id)!;
    const dy = (rank.index - (rank.count - 1) / 2) * DUPLICATE_FAN_PX;
    return { index: rank.index, count: rank.count, offset: { dx: 0, dy } };
  });
}

// src/hosts/frameScene.ts — this host family's FRAME vocabulary
// (`HostNodeData.frame`, `type: "frame"`) and the writes a frame's port
// edges make: add a wall port, remove one, split a cable through a wall,
// unsplit it, and delete with the link set. Pure: no React, no DOM — it
// lives in `hosts/` only because it reads `HostNodeData`, which the scene
// kit never learns about (the same licence `regionScene.ts` claims).
//
// The scene-side rules are `scene/wallPort.ts` (crossings, faces, the
// chain split) and `scene/links.ts` (the linked set); this file binds them
// to where THIS host keeps its ports (`data.ports[side]`, `portLabels`,
// `portTypes`) and to the frame's own per-wall settings.
//
// WHY every behaviour here is a TOGGLE in the data, not a fixed rule
// (Zach, 2026-09-22: "These are all toggable as we may use in different
// scenarios"): `frame.crossings` (`off` | `ring` | `port`), `frame.arrange`
// per wall (`auto` | `custom`), and the validation switch a story holds —
// each is a field a host reads, never a constant a component bakes in.
//
// WHY a split-minted port carries EXPLICIT faces (`frame.faces[portId]`):
// the wall's convention (left/top receive, right/bottom emit —
// `hostScene.ts`'s `SINK_SIDES`) is the DEFAULT face of a port someone
// placed by hand, but a cable that was split ENTERED or LEFT through a
// specific wall, and with validation off that can be an input through the
// right wall. The faces of that port are a fact about the cable it was cut
// from, so they are written down rather than re-derived from the wall.

import { insertPortAtWall, isInnerFaceHandle, isReservedPortId, outerPortIdOf, type WallTrack } from "../components/frame.layout";
import type { FrameFit, FrameSurface, FrameTitlePlacement } from "../components/frame";
import type { BlockSide } from "../components/port.layout";
import type { PortEdgeArrangeMode } from "../components/portEdge";
import { deleteWithLinks, type DeleteWithLinksResult, type ObjectRef } from "../scene/links";
import type { PortDirectionOf, PortsOf, PortTypeOf } from "../scene/model";
import { childrenOf, type SceneNode } from "../scene/scene";
import {
  splitEdgeAtWalls,
  unsplitWallPort,
  wallFacesFor,
  withFaceTypes,
  withInnerFaces,
  withWallFaces,
  type SplitAtWallsResult,
  type WallCrossing,
  type WallFace,
  type WallPortFaces,
} from "../scene/wallPort";
import { hostPolarityOf, hostPortsOf, type HostNodeData, type HostScene } from "./hostScene";

/* ------------------------------------------------------------------ */
/* Vocabulary                                                          */
/* ------------------------------------------------------------------ */

/** `SceneNode.type` for a frame. One spelling, in one place. */
export const FRAME_NODE_TYPE = "frame";

/**
 * What a frame does where a cable crosses its wall. Detection runs in every
 * mode — this only decides what is DRAWN or MINTED:
 *   `off`  — nothing;
 *   `ring` — a small hollow ring at the crossing (Option 1);
 *   `port` — a real port on the wall, the cable split through it (Option 2).
 */
export type FrameCrossingMode = "off" | "ring" | "port";

/** `data.frame` on a `type: "frame"` node — the frame's own toggles. The
 *  ports themselves stay in `data.ports`, exactly as a block's do, so every
 *  reader of `ports`/`portLabels`/`portTypes` works on a frame unchanged. */
export interface FrameData {
  /** Default `"ring"`. */
  crossings?: FrameCrossingMode;
  /** Per-wall spacing mode. Absent = `"auto"`. */
  arrange?: Partial<Record<BlockSide, PortEdgeArrangeMode>>;
  /** Custom mode's slot offsets, per wall (`PortEdge.freeOffsets`). */
  offsets?: Partial<Record<BlockSide, Record<string, number>>>;
  /** Explicit faces per port id. Absent = derived from the wall. */
  faces?: Record<string, WallPortFaces>;
  titlePlacement?: FrameTitlePlacement;
  surface?: FrameSurface;
  fit?: FrameFit;
  showPortEdgeLines?: boolean;
  /** Which walls carry a port edge. Absent = all four. */
  portEdges?: BlockSide[];
}

export function isFrameNode(node: SceneNode<HostNodeData>): boolean {
  return node.type === FRAME_NODE_TYPE;
}

/**
 * Which nodes have WALLS a cable can cross: a frame, or an expanded block
 * that holds members. Detection runs against these; port INSERTION is a
 * frame's (a block's rail has no inner face yet — docs/FRAME-PLAN.md).
 */
export function isWallContainer(scene: HostScene, node: SceneNode<HostNodeData>): boolean {
  if (isFrameNode(node)) return true;
  return (node.type ?? "block") === "block" && node.data.view === "expanded" && childrenOf(scene, node.id).length > 0;
}

export function wallContainerIds(scene: HostScene): string[] {
  return scene.nodes.filter((node) => isWallContainer(scene, node)).map((node) => node.id);
}

export function frameCrossingMode(node: SceneNode<HostNodeData>): FrameCrossingMode {
  return node.data.frame?.crossings ?? "ring";
}

function writeFrame(scene: HostScene, frameId: string, patch: Partial<FrameData>): HostScene {
  const index = scene.nodes.findIndex((node) => node.id === frameId);
  if (index === -1) return scene;
  const node = scene.nodes[index];
  const nodes = scene.nodes.slice();
  nodes[index] = { ...node, data: { ...node.data, frame: { ...(node.data.frame ?? {}), ...patch } } };
  return { ...scene, nodes };
}

/** The mode toggle, as a scene write: ONE field on ONE node. */
export function setFrameCrossingMode(scene: HostScene, frameId: string, mode: FrameCrossingMode): HostScene {
  const node = scene.nodes.find((candidate) => candidate.id === frameId);
  if (!node || frameCrossingMode(node) === mode) return scene;
  return writeFrame(scene, frameId, { crossings: mode });
}

export function setWallArrange(scene: HostScene, frameId: string, side: BlockSide, arrange: PortEdgeArrangeMode): HostScene {
  const node = scene.nodes.find((candidate) => candidate.id === frameId);
  if (!node || (node.data.frame?.arrange?.[side] ?? "auto") === arrange) return scene;
  return writeFrame(scene, frameId, { arrange: { ...(node.data.frame?.arrange ?? {}), [side]: arrange } });
}

export function setWallOffsets(scene: HostScene, frameId: string, side: BlockSide, offsets: Record<string, number>): HostScene {
  const node = scene.nodes.find((candidate) => candidate.id === frameId);
  if (!node) return scene;
  return writeFrame(scene, frameId, { offsets: { ...(node.data.frame?.offsets ?? {}), [side]: offsets } });
}

/* ------------------------------------------------------------------ */
/* Ports on a wall — reading                                           */
/* ------------------------------------------------------------------ */

/** The wall an AUTHORED port sits on — `data.ports` exactly as written,
 *  no face grammar applied. */
function sideOfAuthored(node: SceneNode<HostNodeData>, portId: string): BlockSide | undefined {
  for (const side of Object.keys(node.data.ports ?? {}) as BlockSide[]) {
    if ((node.data.ports?.[side] ?? []).includes(portId)) return side;
  }
  return undefined;
}

/** What a handle on a node's wall names, resolved STRUCTURALLY. */
export interface WallHandle {
  /** The authored port. */
  portId: string;
  side: BlockSide;
  face: WallFace;
}

/**
 * Which authored port, on which wall, through which face a handle names —
 * and the one rule that makes `@inner` safe (judge round 1, finding 7):
 * an AUTHORED id wins. `temperature@inner` written into `data.ports` is
 * that port's own outer face; only a handle that is NOT authored, spells
 * `<p>@inner`, and whose `<p>` IS authored, is `<p>`'s inner face.
 * `undefined` for anything else.
 */
export function resolveWallHandle(node: SceneNode<HostNodeData>, handle: string): WallHandle | undefined {
  const authored = sideOfAuthored(node, handle);
  if (authored !== undefined) return { portId: handle, side: authored, face: "outer" };
  if (isInnerFaceHandle(handle)) {
    const outer = outerPortIdOf(handle);
    const side = sideOfAuthored(node, outer);
    if (side !== undefined) return { portId: outer, side, face: "inner" };
  }
  return undefined;
}

/** The wall a port sits on, or `undefined` when the node does not carry
 *  it. Accepts either face's handle (`resolveWallHandle`). */
export function sideOfPort(node: SceneNode<HostNodeData>, portId: string): BlockSide | undefined {
  return resolveWallHandle(node, portId)?.side;
}

export function wallPortExists(scene: HostScene, nodeId: string, portId: string): boolean {
  const node = scene.nodes.find((candidate) => candidate.id === nodeId);
  return node !== undefined && sideOfPort(node, portId) !== undefined;
}

/** `true` when `ref.portId` is written into `ref.nodeId`'s `data.ports` —
 *  the structural test every face resolver here is built on. */
export function isAuthoredPort(scene: HostScene): (ref: { nodeId: string; portId: string }) => boolean {
  const byId = new Map(scene.nodes.map((node) => [node.id, node]));
  return (ref) => {
    const node = byId.get(ref.nodeId);
    return node !== undefined && sideOfAuthored(node, ref.portId) !== undefined;
  };
}

/** A wall port's two faces, keyed by its AUTHORED id: the explicit record
 *  when the host wrote one, else derived from the wall's own convention.
 *  `undefined` for anything that is not an authored port on a wall
 *  container. */
export function frameFacesOf(scene: HostScene): (ref: { nodeId: string; portId: string }) => WallPortFaces | undefined {
  const polarity = hostPolarityOf(scene);
  return (ref) => {
    const node = scene.nodes.find((candidate) => candidate.id === ref.nodeId);
    if (!node || !isWallContainer(scene, node) || sideOfAuthored(node, ref.portId) === undefined) return undefined;
    const explicit = node.data.frame?.faces?.[ref.portId];
    if (explicit) return explicit;
    const outer = polarity(ref);
    return outer === undefined ? undefined : wallFacesFor(outer);
  };
}

/** `hostPortsOf` + every wall port's inner face (an authored id that
 *  already spells one is left as the one port it is). */
export function framePortsOf(scene: HostScene): PortsOf {
  const byId = new Map(scene.nodes.map((node) => [node.id, node]));
  return withInnerFaces(hostPortsOf(scene), (nodeId) => {
    const node = byId.get(nodeId);
    return node !== undefined && isWallContainer(scene, node);
  });
}

/** `hostPolarityOf` + the faces, resolved structurally. */
export function frameDirectionOf(scene: HostScene): PortDirectionOf {
  return withWallFaces(hostPolarityOf(scene), frameFacesOf(scene), isAuthoredPort(scene));
}

/** `data.portTypes[port]` as a one-tag vocabulary, for either face.
 *  `undefined` (no declared type) means "unconstrained", `lint.ts`'s
 *  convention. */
export function frameTypeOf(scene: HostScene): PortTypeOf {
  const byId = new Map(scene.nodes.map((node) => [node.id, node]));
  return withFaceTypes((ref) => {
    const type = byId.get(ref.nodeId)?.data.portTypes?.[ref.portId];
    return type === undefined ? undefined : [type];
  }, isAuthoredPort(scene));
}

/* ------------------------------------------------------------------ */
/* Ports on a wall — writing                                           */
/* ------------------------------------------------------------------ */

export interface AddWallPortInput {
  containerId: string;
  side: BlockSide;
  portId: string;
  /** Where along the wall, 0..1 — decides the ORDER in auto mode and the
   *  offset in custom mode. Absent = append. */
  t?: number;
  label?: string;
  type?: string;
  faces?: WallPortFaces;
  /** The wall's measured track (`frame.layout.ts`'s `wallTrack`) — needed
   *  to place by `t`. Absent = append to the wall's order. */
  track?: WallTrack;
}

/**
 * Put a port on a wall. In AUTO mode the port takes the index its `t`
 * implies and the edge re-spaces it; in CUSTOM mode it stays where the
 * cable crossed, clamped by order and the minimum gap
 * (`insertPortAtWall`). A port that already exists is a no-op.
 */
export function addWallPort(scene: HostScene, input: AddWallPortInput): HostScene {
  // The face marker is reserved for handles this kit derives; a minted id
  // that contained it would be one string with two meanings (finding 7).
  if (isReservedPortId(input.portId)) return scene;
  const index = scene.nodes.findIndex((node) => node.id === input.containerId);
  if (index === -1) return scene;
  const node = scene.nodes[index];
  if (sideOfPort(node, input.portId) !== undefined) return scene;
  const order = node.data.ports?.[input.side] ?? [];
  const arrange = node.data.frame?.arrange?.[input.side] ?? "auto";
  const stored = node.data.frame?.offsets?.[input.side];
  let nextOrder: string[];
  let nextOffsets: Record<string, number> | undefined = stored;
  if (input.t !== undefined && input.track) {
    const placed = insertPortAtWall({
      order,
      offsets: stored,
      mode: arrange,
      distribution: { mode: "distribute", scheme: "space-evenly" },
      track: input.track,
      id: input.portId,
      t: input.t,
    });
    nextOrder = placed.order;
    if (arrange === "custom") nextOffsets = placed.offsets;
  } else {
    nextOrder = [...order, input.portId];
  }
  const data: HostNodeData = {
    ...node.data,
    ports: { ...(node.data.ports ?? {}), [input.side]: nextOrder },
    ...(input.label === undefined ? {} : { portLabels: { ...(node.data.portLabels ?? {}), [input.portId]: input.label } }),
    ...(input.type === undefined ? {} : { portTypes: { ...(node.data.portTypes ?? {}), [input.portId]: input.type } }),
  };
  if (input.faces || nextOffsets !== stored) {
    data.frame = {
      ...(node.data.frame ?? {}),
      ...(input.faces ? { faces: { ...(node.data.frame?.faces ?? {}), [input.portId]: input.faces } } : {}),
      ...(nextOffsets !== stored ? { offsets: { ...(node.data.frame?.offsets ?? {}), [input.side]: nextOffsets ?? {} } } : {}),
    };
  }
  const nodes = scene.nodes.slice();
  nodes[index] = { ...node, data };
  return { ...scene, nodes };
}

/** Take a port off its wall — its label, type, faces and offset with it.
 *  Edges naming it are NOT touched here (that is `deleteWithLinks`'s or
 *  the caller's decision). Unknown port: the same scene. */
export function removeWallPort(scene: HostScene, ref: { nodeId: string; portId: string }): HostScene {
  const index = scene.nodes.findIndex((node) => node.id === ref.nodeId);
  if (index === -1) return scene;
  const node = scene.nodes[index];
  const resolved = resolveWallHandle(node, ref.portId);
  if (resolved === undefined) return scene;
  const { side, portId } = resolved;
  // A record with the port's entry removed — and NO record at all once it
  // is empty, so add → remove leaves the node byte-identical (finding 5's
  // round trip: `portLabels: {}` is not "no labels").
  const without = <T,>(record: Record<string, T> | undefined): Record<string, T> | undefined => {
    if (!record || !(portId in record)) return record;
    const { [portId]: _gone, ...rest } = record;
    return Object.keys(rest).length === 0 ? undefined : rest;
  };
  const setOrDrop = (target: Record<string, unknown>, key: string, value: unknown): void => {
    if (value === undefined) delete target[key];
    else target[key] = value;
  };
  const data: HostNodeData = {
    ...node.data,
    ports: { ...(node.data.ports ?? {}), [side]: (node.data.ports?.[side] ?? []).filter((id) => id !== portId) },
  };
  setOrDrop(data as Record<string, unknown>, "portLabels", without(node.data.portLabels));
  setOrDrop(data as Record<string, unknown>, "portTypes", without(node.data.portTypes));
  const frame = node.data.frame;
  if (frame) {
    const nextFrame: Record<string, unknown> = { ...frame };
    setOrDrop(nextFrame, "faces", without(frame.faces));
    if (frame.offsets) {
      const offsets: Record<string, Record<string, number>> = { ...(frame.offsets as Record<string, Record<string, number>>) };
      const sideOffsets = without(offsets[side]);
      if (sideOffsets) offsets[side] = sideOffsets;
      else delete offsets[side];
      setOrDrop(nextFrame, "offsets", Object.keys(offsets).length === 0 ? undefined : offsets);
    }
    setOrDrop(data as Record<string, unknown>, "frame", Object.keys(nextFrame).length === 0 ? undefined : nextFrame);
  }
  const nodes = scene.nodes.slice();
  nodes[index] = { ...node, data };
  return { ...scene, nodes };
}

/* ------------------------------------------------------------------ */
/* The split, bound to this host's ports                               */
/* ------------------------------------------------------------------ */

export interface SplitAtFrameWallsOptions {
  /** The wall's measured track, so the minted port lands where the cable
   *  crossed. Absent = appended to the wall's order. */
  trackOf?(containerId: string, side: BlockSide): WallTrack | undefined;
  /** Default: `<containerId>:<edgeId>:<i>`. */
  mintPortId?(crossing: WallCrossing, index: number, edgeId: string): string;
  /** The label every minted port wears. Default `"port"` (Zach's sketch). */
  label?: string;
}

/**
 * `splitEdgeAtWalls` with this host's `addPort`: the minted port takes the
 * cable's declared TYPE (the source end's, else the target's — `data.
 * portTypes`) and EXPLICIT faces from the crossing's direction (entering →
 * the outer face receives; leaving → it emits), and lands where the cable
 * crossed.
 */
export function splitEdgeAtFrameWalls(
  scene: HostScene,
  edgeId: string,
  crossings: readonly WallCrossing[],
  options: SplitAtFrameWallsOptions = {},
): SplitAtWallsResult<HostNodeData, NonNullable<HostScene["edges"][number]["data"]>> {
  const edge = scene.edges.find((candidate) => candidate.id === edgeId);
  if (!edge) return { scene, ports: [] };
  const typeOf = frameTypeOf(scene);
  const sourceType = edge.sourceHandle ? typeOf({ nodeId: edge.source, portId: edge.sourceHandle })?.[0] : undefined;
  const targetType = edge.targetHandle ? typeOf({ nodeId: edge.target, portId: edge.targetHandle })?.[0] : undefined;
  const type = sourceType ?? targetType;
  return splitEdgeAtWalls(scene, edgeId, crossings, {
    mintPortId: (crossing, index) => options.mintPortId?.(crossing, index, edgeId) ?? `${crossing.containerId}:${edgeId}:${index}`,
    addPort: (current, port) =>
      addWallPort(current, {
        containerId: port.containerId,
        side: port.crossing.side,
        portId: port.portId,
        t: port.crossing.t,
        label: options.label ?? "port",
        ...(type === undefined ? {} : { type }),
        faces: port.crossing.direction === "enter" ? wallFacesFor("sink") : wallFacesFor("source"),
        track: options.trackOf?.(port.containerId, port.crossing.side),
      }),
  });
}

/** `unsplitWallPort` with this host's `removePort`. */
export function unsplitFrameWallPort(scene: HostScene, ref: { nodeId: string; portId: string }): HostScene {
  return unsplitWallPort(scene, { containerId: ref.nodeId, portId: ref.portId }, { removePort: (current, port) => removeWallPort(current, { nodeId: port.containerId, portId: port.portId }) });
}

/** `deleteWithLinks` with this host's port ops — the one delete a frame
 *  story wires the Delete key to. */
export function deleteFrameObjects(scene: HostScene, refs: Iterable<ObjectRef>): DeleteWithLinksResult<HostNodeData, NonNullable<HostScene["edges"][number]["data"]>> {
  return deleteWithLinks(scene, refs, {
    deletePort: (current, nodeId, portId) => removeWallPort(current, { nodeId, portId }),
    portExists: wallPortExists,
  });
}

// src/hosts/hostScene.ts — ONE scene literal shared by every host bench.
//
// H1's contract claim ("one scene, two hosts, no per-host fixture") is only
// falsifiable if both host stories import the SAME record — a copy per host
// would let the fixtures drift apart and each host quietly render its own
// truth. So the literal lives here, beside the hosts, and the story files
// import it; neither host module hardcodes a node.
//
// `HostNodeData` is what THIS host family stores per node — the scene kit
// never knows these fields exist (they are `data` to it, the same licence
// `Scene.stories.tsx`'s `NodeView` already exercises). `node.type` carries
// the HOST-FACING component name (Zach's table, 2026-09-17): `glyph` →
// Glyph, `code` → Code (CodeEditor), `block` → Block (BlockPort), `value` →
// Value (ValueCapsule). Loop and Branch are absent because those presets do
// not exist yet — verified against src/presets/ (only `value/`) before this
// fixture was written.

import type { BlockSide } from "../components/port.layout";
import type { BlockView } from "../components/blockPort.layout";
import type { PortDirection, PortDirectionOf, PortsOf } from "../scene/lint";
import type { BlockMembersLayout } from "../components/blockMembers";
import type { BlockScene } from "../scene/scene";
import type { WireStyleData } from "../scene/sceneWires";

export type HostNodeData = {
  /** Display name — data, free to collide; never identity. */
  name?: string;
  /* -- type: "block" ------------------------------------------------ */
  view?: BlockView;
  w?: number;
  h?: number;
  /** Which wall each port sits on — VIEW geometry, host-owned. The scene
   *  only ever names ports; it never places them. */
  ports?: Partial<Record<BlockSide, string[]>>;
  /** Walls whose ports hug the header end instead of centring — the donor
   *  bench's own device (Scene.stories.tsx), kept for the same reason:
   *  proc's own `in` dot stays visually clear of its member's dot. */
  anchorStart?: BlockSide[];
  /**
   * How THIS node's own members are laid out. Absent → `"stack"`, the
   * behaviour every existing story already renders (`BlockNodeView`
   * hardcoded it before this field existed) — so leaving it unset is
   * byte-identical to before this lane. `"free"` opts a node into the
   * `fit-to-content-hosts` lane's wiring: its members carry their own
   * `position`, read as the member's (x, y) inside this node's members
   * region — which is exactly `SceneNode.position`'s own documented
   * contract (scene.ts:60-72, "the node's authored at-rest placement, in
   * the PARENT's coordinate space when `parentId` is set"). That sentence
   * predates this lane; nothing before it ever wrote or read a member's
   * position, so free layout was contractually possible but never wired.
   */
  membersLayout?: BlockMembersLayout;
  /** Fit this node's height to its free-mode members' measured extents
   *  (`fitToContent.ts`'s `blockExpandedFitHeight`) instead of `data.h`.
   *  Ignored unless `membersLayout === "free"`. See `nodeViews.tsx`'s
   *  `BlockNodeView` for the wiring and the reentrancy guard. */
  autoFit?: boolean;
  /* -- type: "glyph" ------------------------------------------------ */
  /** `@bbox-ui/glyph-content` grammar, e.g. `lucide:rocket`. */
  content?: string;
  /* -- type: "code" ------------------------------------------------- */
  code?: string;
  /* -- type: "value" ------------------------------------------------ */
  value?: string;
  writers?: string[];
  readers?: string[];
  /* -- type: "region" (scene/region.ts's REGION_NODE_TYPE) ------------- */
  /** The control-flow vocabulary — see `hosts/regionScene.ts`. A region's
   *  CORNER BLOCK reads `name`, `ports`, `w`/`h` exactly as a `block` does:
   *  the corner block IS this node's interface ("everything is a block"),
   *  and the frame around it carries scope and no value ports
   *  (docs/CONTROL-FLOW-PLAN.md). */
  region?: import("./regionScene").RegionData;
  /** A chip in the corner block's header — a loop's "iteration 3 of 7"
   *  (donor loopModel.ts:77-78's `turn`, generalised to any region). */
  badge?: string;
  /* -- type: "arm" (scene/controlFlow.ts's ARM_NODE_TYPE) --------------- */
  arm?: import("./regionScene").ArmData;
  /* -- type: "frame" (hosts/frameScene.ts's FRAME_NODE_TYPE) ------------- */
  /** The frame's own toggles (crossing mode, per-wall spacing, faces). A
   *  frame's PORTS stay in `ports`/`portLabels`/`portTypes` exactly as a
   *  block's do, and its members are its `parentId` children — the frame
   *  owns membership and layout (Zach, 2026-09-22), the data does not move.
   *  ADDED 2026-09-22, lane `frame-auto-port-edges`. */
  frame?: import("./frameScene").FrameData;
  /* -- any block ------------------------------------------------------ */
  /** Port id → the port's authored NAME. Only NAMED ports appear; an
   *  absent entry means "no authored label" and the face falls back to the
   *  port ID, which is this family's own default (`nodeViews.tsx`'s port
   *  item builder).
   *
   *  WHY the id stays the id and a label is a separate bag, rather than
   *  renaming the port: the id is what an edge's `sourceHandle` names and
   *  what an edit event names the block's port with (a pyblocks document's
   *  ids are semantic — `in-raw`, `boundary-output-scaled`), so renaming
   *  it to the display name would break both. And the label is rendered
   *  literally, never normalized or clipped (`feedback_truthful_property_
   *  rendering`). */
  portLabels?: Record<string, string>;
  /** Port id → the declared type text, when the producer had one. Data
   *  only — nothing in this family paints it yet. */
  portTypes?: Record<string, string>;
  /**
   * Port id → the expression that is in force while NOTHING is wired to it.
   *
   * This is what makes a port read as `PortState "valueSet"` — "owns a
   * default" (`components/port.tsx:60`) — rather than `empty`. A `for`
   * loop's `Iterable` showing `range(10)`, a `while`'s `Bool` showing
   * `last_error != ""`: the value is really there, it just arrived by being
   * typed rather than by cable, and the drawing has to say which.
   *
   * WHY it belongs here beside `portLabels` rather than on any one region
   * kind: an unwired port that owns a default is a fact about PORTS, not
   * about loops. Arms already carry theirs (`ArmData.test.default`) because
   * an arm's operand is part of the arm's own identity; every other port in
   * every host had no seam at all, so a scene-built loop could not show an
   * inline default while a hand-mounted `BlockRegion` could — measured
   * 2026-09-22 when the loop stories had to bypass the scene to draw one.
   *
   * A CABLE ALWAYS WINS: `withWiredState` runs after this and overwrites
   * `valueSet` with `wired`, which is the correct precedence — a default is
   * what you get in the absence of a value, never instead of one.
   *
   * Rendered literally, never normalized or clipped
   * (`feedback_truthful_property_rendering`): `  range(10)  ` keeps its
   * spaces.
   */
  portDefaults?: Record<string, string>;
  /** Control-exit marks. DP - Break & Continue, B5: a mark beside the call,
   *  never a cable — "break is not data flow". Drawn as badges, no wire. */
  marks?: ("break" | "continue" | "pass")[];
};

