  severity: "warning",
  title: "Duplicate edge — 2+ edges share one unordered port pair",
  provenance: "wraps duplicateEdges (scene.ts:373); severity per wiring.ts:20-22's stated permission-free stance",
  run(scene) {
    const hits: LintRuleHit[] = [];
    for (const group of duplicateEdges(scene)) {
      const message = `${group.length} edges connect the same two ports`;
      for (const edge of group) hits.push({ subject: { kind: "edge", id: edge.id }, message });
    }
    return hits;
  },
};

const manyToOneRule: LintRule = {
  id: "many-to-one",
  severity: "error",
  title: "Many-to-one — 2+ producers wired into one input port",
  provenance:
    'PROJECT - pyblocks § many-to-one (vault, AI answer 2026-09-02): "two producers into one port are legal only when some region makes them exclusive... two producers outside every region are never exclusive." This scene kit has no region/branch/arm concept (grepped: none exists in src/scene or src/components), so the exclusivity carve-out never applies yet — every hit here is unconditionally illegal until a region model exists. Message wording matches the precedent already in Diagnostics.stories.tsx\'s `WiredAndError` story ("Two producers wired into one port"), which marks the PORT, not an edge — this rule does the same. Counts DISTINCT SOURCES, not raw producer-edge count (see the `run` body\'s own WHY) — an exact re-wire from the same source is duplicate-edge\'s concern, not this rule\'s.',
  run(scene) {
    const seen = new Set<string>();
    const hits: LintRuleHit[] = [];
    for (const edge of scene.edges) {
      if (edge.targetHandle == null) continue;
      const ref: ScenePortRef = { nodeId: edge.target, portId: edge.targetHandle };
      const key = portKey(ref.nodeId, ref.portId);
      if (seen.has(key)) continue;
      seen.add(key);
      const producers = producersOf(scene, ref);
      // Distinct SOURCES, not raw edge count. Two edges from the exact same
      // source port carry the identical value — that is `duplicate-edge`'s
      // concern (a redundant wire, warning-severity and explicitly PERMITTED
      // by wiring.ts's own stance), not a contended one. Many-to-one is
      // about genuinely different values competing for one port with no
      // region to choose between them (the pyblocks φ framing this rule is
      // ported from) — an exact re-wire of the same source is not that.
      const distinctSources = new Set(producers.map((p) => portKey(p.source, p.sourceHandle ?? "")));
      if (distinctSources.size < 2) continue;
      hits.push({
        subject: { kind: "port", id: key },
        message: `Port "${key}" has ${distinctSources.size} producers wired in (no region makes them exclusive)`,
      });
    }
    return hits;
  },
};

const selfConnectionRule: LintRule = {
  id: "self-connection",
  severity: "error",
  title: "Self-connection — an edge's source and target are the same node",
  provenance:
    "ours, ad hoc. findCycles (scene.ts:297-301) already detects a self-loop structurally while building its SCCs, but reports the NODE id, never the edge id — this rule reports the WIRE directly (source === target) so the offending edge, not just the node, carries a mark.",
  run(scene) {
    return scene.edges
      .filter((edge) => edge.source === edge.target)
      .map((edge) => ({ subject: { kind: "edge", id: edge.id }, message: `Edge "${edge.id}" connects "${edge.source}" to itself` }));
  },
};

const typeMismatchRule: LintRule = {
  id: "type-mismatch",
  severity: "error",
  title: "Type mismatch — an edge connects two incompatible port types",
  provenance:
    "Blockly ConnectionChecker.doTypeChecks (Apache-2.0, fetched github.com/google/blockly main core/connection_checker.ts:203-219) — list-intersection compatibility. maxGraph Multiplicity.check was the planned donor and was REJECTED: checkTerminal(graph, source_or_target, edge) receives the connecting EDGE in the parameter named `terminal` (Multiplicity.ts:147-150 vs the call site at :204-208, v0.24.0), so it silently no-ops for every ordinary edge — reproduced against maxGraph's own Validation-story fixtures. Fires ONLY when the caller-supplied `typeOf` resolves a vocabulary for BOTH ends — see this file's header for why no vocabulary is minted here.",
  run(scene, context) {
    const typeOf = context?.typeOf;
    if (!typeOf) return [];
    const compatible = context?.compatible ?? typesIntersect;
    const hits: LintRuleHit[] = [];
    for (const edge of scene.edges) {
      if (edge.sourceHandle == null || edge.targetHandle == null) continue;
      const sourceTypes = typeOf({ nodeId: edge.source, portId: edge.sourceHandle });
      const targetTypes = typeOf({ nodeId: edge.target, portId: edge.targetHandle });
      // Either end unresolved -> no judgement, per PortsOf's own
      // "undefined = unknown" convention. Fabricating a verdict from a
      // half-known vocabulary is exactly the "invent a rule the data
      // cannot support" trap this file's header already warns against.
      if (!sourceTypes || !targetTypes) continue;
      if (compatible(sourceTypes, targetTypes)) continue;
      hits.push({
        subject: { kind: "edge", id: edge.id },
        message: `Edge "${edge.id}" carries "${sourceTypes.join(", ")}" into "${targetTypes.join(", ")}"`,
      });
    }
    return hits;
  },
};


/**
 * `polarity` — an edge whose ends do not read SOURCE port -> SINK port.
 *
 * Two genuinely different at-rest wrongs, one rule, because both are the
 * same question ("which way does this port face?") and splitting them would
 * put one rule's answer out of reach of the other:
 *
 *   same-direction  both ends emit, or both receive. Nothing can flow. This
 *                   is the one `validateConnection` REFUSES (donor name
 *                   `same-polarity`, `connectionRules.ts:186`, opened).
 *   reversed        the ends are legitimately opposite, but the edge names
 *                   them backwards: its `source` is a SINK. The pair is
 *                   legal; only the writing is wrong. At DRAG time this is
 *                   never a refusal — the judge simply orients it (donor
 *                   `decideDirection`, `connectionRules.ts:222-234`, opened,
 *                   which flips rather than refuses). It can only reach a
 *                   scene by some path that did not go through the judge —
 *                   an import, a hand-authored fixture, or a caller that
 *                   ignored the verdict's oriented pair — which is exactly
 *                   why the ANNOTATION half has to be able to say it.
 *
 * Inert without `directionOf`, per this file's "undefined = unknown, no
 * judgement" convention: every scene linted before 2026-09-18 yields
 * byte-identical findings.
 */
const polarityRule: LintRule = {
  id: "polarity",
  severity: "error",
  title: "Polarity \u2014 an edge does not run from a source port to a sink port",
  provenance:
    "SystemSketch src/blocks/connections/connectionRules.ts:186 (the `same-polarity` refusal) and :222-234 (`decideDirection`, which resolves the reversed case by FLIPPING rather than refusing) \u2014 both opened on disk. The donor derives polarity from `portPolarity(port.side, face)` (connectionModel.ts:99); this kit has neither lanes nor faces in its scene model, so direction is supplied by a caller-side `PortDirectionOf` resolver instead of computed. Reversed-as-a-FINDING is ours: the donor has a gesture to flip and a scene at rest does not.",
  run(scene, context) {
    const directionOf = context?.directionOf;
    if (!directionOf) return [];
    const hits: LintRuleHit[] = [];
    for (const edge of scene.edges) {
      if (edge.sourceHandle == null || edge.targetHandle == null) continue;
      const from = directionOf({ nodeId: edge.source, portId: edge.sourceHandle });
      const to = directionOf({ nodeId: edge.target, portId: edge.targetHandle });
      // Either end unresolved -> no judgement, exactly as `type-mismatch`
      // treats a half-known type vocabulary.
      if (from === undefined || to === undefined) continue;
      if (from === to) {
        hits.push({
          subject: { kind: "edge", id: edge.id },
          message: `Edge "${edge.id}" joins two ${from} ports \u2014 "${edge.source}/${edge.sourceHandle}" and "${edge.target}/${edge.targetHandle}"`,
          detail: "same-direction",
        });
        continue;
      }
      if (from === "sink") {
        hits.push({
          subject: { kind: "edge", id: edge.id },
          message: `Edge "${edge.id}" runs backwards \u2014 its source "${edge.source}/${edge.sourceHandle}" is a sink`,
          detail: "reversed",
        });
      }
    }
    return hits;
  },
};

/** The closed registry — a documented value per id, never an open string
 *  soup. `Readonly` so a consumer cannot quietly monkey-patch a rule. */
export const LINT_RULES: Readonly<Record<LintRuleId, LintRule>> = {
  "dangling-edge": danglingEdgeRule,
  cycle: cycleRule,
  "duplicate-edge": duplicateEdgeRule,
  "many-to-one": manyToOneRule,
  "self-connection": selfConnectionRule,
  "type-mismatch": typeMismatchRule,
  polarity: polarityRule,
};

/* ------------------------------------------------------------------ */
/* The runner                                                          */
/* ------------------------------------------------------------------ */

export interface LintOptions {
  /**
   * Which rules run this pass. Omitted = every rule in `LINT_RULE_IDS`.
   * This is the whole mechanism behind Zach's requirement — "if you only
   * have a subset of the rules on then only a subset of the traces are in
   * error state" — a rule that is not in this list contributes NOTHING,
   * not even a suppressed finding; there is no monolithic `lint(scene)`
   * that always runs everything and hides some of it after the fact.
   */
  rules?: readonly LintRuleId[];
  portsOf?: PortsOf;
  /** `type-mismatch`'s vocabulary — omitted, that rule contributes nothing
   *  (see its own `run`). Every existing caller that never passes these
   *  gets byte-identical findings to before this field existed. */
  typeOf?: PortTypeOf;
  compatible?: TypeCompatible;
  /** `polarity`'s vocabulary — same "omitted = that rule contributes
   *  nothing" contract as `typeOf` directly above. */
  directionOf?: PortDirectionOf;
}

/**
 * scene, enabled rules -> findings. Pure and total: an unknown rule id in
 * `options.rules` is skipped rather than thrown on (the same malformed-
 * input policy `dependencyGraph`/`findDanglingEdges` already use), and an
 * empty scene or an empty rule set both yield `[]`, the honest nothing.
 *
 * One finding per (rule, subject) is the norm; a rule may still emit more
 * than one hit for the SAME subject in a single pass when the underlying
 * facts are genuinely independent (an edge dangling at both ends) — the
 * `detail` on that hit is what keeps the resulting ids distinct rather than
 * colliding, per `LintFinding.id`'s own doc.
 */
export function lintScene(scene: LintScene, options: LintOptions = {}): LintFinding[] {
  const ruleIds = options.rules ?? LINT_RULE_IDS;
  const context: LintRuleContext = { portsOf: options.portsOf, typeOf: options.typeOf, compatible: options.compatible, directionOf: options.directionOf };
  const findings: LintFinding[] = [];
  for (const ruleId of ruleIds) {
    const rule = LINT_RULES[ruleId];
    if (!rule) continue;
    for (const hit of rule.run(scene, context)) {
      const subjectKeyStr = `${hit.subject.kind}:${hit.subject.id}`;
      const id = hit.detail ? `lint:${rule.id}:${subjectKeyStr}:${hit.detail}` : `lint:${rule.id}:${subjectKeyStr}`;
      findings.push({ id, severity: rule.severity, message: hit.message, code: rule.id, ruleId: rule.id, subject: hit.subject });
    }
  }
  return findings;
}

/* ------------------------------------------------------------------ */
/* Reading the result — grouped by render carrier                      */
/* ------------------------------------------------------------------ */

/** `${kind}:${id}` — the one shared spelling of "which carrier", mirroring
 *  `scene.ts`'s own `portKey`. */
export function subjectKey(subject: LintSubject): string {
  return `${subject.kind}:${subject.id}`;
}

/**
 * Every finding, grouped by the carrier it names — the shape a host reads
 * off to fill one component's `diagnostics` prop. Never pre-collapses: a
 * carrier with N findings keeps all N; `maxDiagnosticSeverity`
 * (diagnostic.tsx) is what the component itself reduces at paint time, per
 * this axis's own channel-discipline rule (docs/INVALID-STATES-PLAN.md §1:
 * "a producer that has already merged N findings to one has destroyed the
 * rest").
 */
export function findingsBySubject(findings: readonly LintFinding[]): Map<string, LintFinding[]> {
  const grouped = new Map<string, LintFinding[]>();
  for (const finding of findings) {
    const key = subjectKey(finding.subject);
    const bucket = grouped.get(key);
    if (bucket) bucket.push(finding);
    else grouped.set(key, [finding]);
  }
  return grouped;
}

/** One carrier's findings, order-preserved — the single-lookup sibling of
 *  `findingsBySubject` for a host that only needs one node/edge/port at a
 *  time (e.g. a story rendering one `Trace` per scene edge). */
export function findingsFor(findings: readonly LintFinding[], subject: LintSubject): LintFinding[] {
  const key = subjectKey(subject);
  return findings.filter((finding) => subjectKey(finding.subject) === key);
}

// src/scene/model.ts — the scene's own vocabulary, in one file.
//
// WHY this file exists (Zach, 2026-09-21): `scene/` IS the domain model, and
// until now it had no place that said so — 170 exported types spread across
// 33 files, with the record itself declared in `scene.ts` beside the pure
// functions over it, and the port vocabulary declared in `lint.ts` as though
// "which way does a port face" were a linting concern rather than a fact
// about what a scene IS. A reader asking "what is a scene here?" had no file
// to open.
//
// WHAT BELONGS HERE, stated so the next addition is not a judgement call:
// a type that DESCRIBES WHAT A SCENE IS, is imported by five or more files,
// and is not the options-or-result type of one function. That third clause
// is what keeps this from becoming a types dump — `SceneOrder` and
// `DanglingEdgeEnd` are what `topologicalOrder` and `findDanglingEdges`
// RETURN, `LintScene` is a structural slice named for its one consumer, and
// `ConnectionMessage`/`ConnectionVerdict` are one judge's verdict
// vocabulary. All of those read correctly where they are and stay there.
//
// WHAT THIS FILE MAY IMPORT: nothing. Not React, not a canvas engine, not
// `components/`. `scene/` already imports `components/` type-only in 13
// files and that stays legal — but the file everything else imports is not
// where that edge belongs, which is why `WireStyleData` (built from
// `components/trace.layout`'s `TraceVariant`/`TraceRouting`/
// `TraceMarkerEnd`) stayed in `sceneWires.ts`: it describes how a wire is
// PAINTED, not what a scene is.
//
// Every declaration below was MOVED here, not copied — `scene.ts`,
// `lint.ts` and `linking.ts` now re-export from this file, so each type
// still has exactly one declaration site and every existing import keeps
// working. `PortsOf` was additionally declared a second time, identically,
// in `batchWire.ts`; that copy is gone and it imports this one.

/* ------------------------------------------------------------------ */
/* The record                                                          */
/* ------------------------------------------------------------------ */

/** Node/edge `data` payloads. A `type` alias (never an `interface`) is what
 *  hosts should extend with — TS gives object-literal type aliases the
 *  implicit index signature that `Record<string, unknown>` compatibility
 *  (and React Flow's own generics) require; interfaces don't get one. */
export type SceneData = Record<string, unknown>;

export interface ScenePosition {
  x: number;
  y: number;
}

/**
 * One block in the scene. `parentId` IS the nesting — membership is a
 * scene fact, not a layout mode (`blockMembers.tsx` renders it; it does
 * not own it).
 *
 * WHY `position` lives here and `BlockScene` has NO separate `placements`
 * table — argued both ways, decided (docs/SCENE-KIT.md §placement):
 *   FOR a separate table: the repo line "interaction geometry is
 *   host-owned". But that line names hit-testing, snapping, drag and
 *   z-order — the TRANSIENT geometry of a gesture. The same line's first
 *   half says layout geometry is portable and travels; an authored
 *   at-rest position is layout, exactly like `BlockMember.x/y` already is.
 *   AGAINST a separate table: two structures owning one fact is precisely
 *   the split-model disease this kit exists to cure (nesting/placement
 *   were fused in one place and absent everywhere else), and React Flow
 *   makes `position` REQUIRED on the node — a placements side-table would
 *   force every adapter to run a join before the types line up, and the
 *   assignability proof would need a cast, which is the criterion failing.
 * So: `position` is the node's authored at-rest placement, in the parent's
 * coordinate space when `parentId` is set (React Flow's sub-flow rule,
 * kept). A host mid-drag owns the moving copy and writes back here at
 * rest.
 *
 * Identity: `id` is the identity — opaque, unique per scene, never derived
 * from what the node is called. A display name is data (`data.name` by
 * convention), free to collide and free to change without any edge
 * noticing. This is the rule `portLane.ts` had to reconstruct with an LCS
 * diff because port lines carried no id; scene nodes never have that
 * problem because the id travels with the record. `definitionId` marks
 * membership in a definition GROUP — see `linkedCopy` below and
 * `src/scene/linking.ts` for the rules that maintain it.
 */
export interface SceneNode<Data extends SceneData = SceneData> {
  id: string;
  /** Host-interpreted kind (React Flow's `nodeTypes` key). Optional. */
  type?: string;
  /** Authored at-rest placement. See the WHY above. */
  position: ScenePosition;
  /** Required (matching React Flow) so the record travels whole — `{}` is
   *  the honest empty, `undefined` is a hole every adapter must patch. */
  data: Data;
  /** The nesting. Absent = top-level. */
  parentId?: string;
  /** The definition GROUP this node is an occurrence of: an opaque id
   *  shared by every occurrence, minted by the host like a node id and
   *  never equal to one — there is no privileged "definition node", the
   *  definition IS the shared data (the function-definition model:
   *  `src/scene/linking.ts` owns the rules). Absent = a group of one.
   *  Extra field over React Flow's `Node` — structurally invisible to
   *  it, deliberately. */
  definitionId?: string;
}

/**
 * One connection. `source`/`target` are node ids; `sourceHandle`/
 * `targetHandle` are port ids on those nodes — a port is identified by
 * (node id, port id), never globally. Stricter than React Flow in one
 * spot, on purpose: handles are `string | undefined`, not
 * `string | null | undefined` — two spellings of "no handle" is one too
 * many, and `undefined` assigns into React Flow's wider type for free.
 */
export interface SceneEdge<Data extends SceneData = SceneData> {
  id: string;
  /** Host-interpreted kind (React Flow's `edgeTypes` key). Optional. */
  type?: string;
  source: string;
  target: string;
  sourceHandle?: string;
  targetHandle?: string;
  data?: Data;
}

/**
 * A ref to one scene object, for `SceneLink.members`: `node:<id>`,
 * `edge:<id>` or `port:<nodeId>/<portId>` (the port form is `portKey`'s
 * own spelling after the prefix). Built and parsed by `./links.ts`.
 */
export type ObjectRef = string;

/**
 * LINKED OBJECTS (Zach, 2026-09-22): a set of scene objects that are
 * individually selectable, are NOT a group (no box, no position, no
 * containment), and are deleted together — delete any one member and every
 * other member goes too. The first use is a cable split at a frame wall:
 * [outer half-cable, wall port, inner half-cable] is one cable drawn in
 * three pieces. General on purpose ("there are other scenarios when this
 * linked object idea could be used, so make it general"). The rules live in
 * `./links.ts`.
 */
export interface SceneLink {
  id: string;
  members: ObjectRef[];
  /**
   * The ONE object this set was cut from, when the set can be undone back
   * into it — a split cable's original edge (`edge:<id>`), so unsplitting
   * the last wall port restores that exact id rather than a segment's
   * (judge round 1, finding 5). Optional and general: a set that was never
   * cut from anything carries none.
   */
  origin?: ObjectRef;
}

/** The scene: nodes + edges (+ optional link sets). Plain mutable arrays so
 *  a host can hand them straight to its engine (React Flow's
 *  `useNodesState` wants `Node[]`, not `readonly Node[]`); the pure
 *  functions below take `readonly` views and never mutate. */
export interface BlockScene<NodeData extends SceneData = SceneData, EdgeData extends SceneData = SceneData> {
  nodes: SceneNode<NodeData>[];
  edges: SceneEdge<EdgeData>[];
  /**
   * ADDITIVE, OPTIONAL (2026-09-22): the link sets — see `SceneLink`.
   * Absent means none, so every scene literal written before this field
   * existed keeps its exact meaning, and every pure function that spreads
   * `...scene` carries the sets through untouched. React Flow's `Node`/
   * `Edge` types never see it (`scene.reactflow.test.ts`'s assignability
   * is per node/edge, not per scene).
   */
  links?: SceneLink[];
}


/* ------------------------------------------------------------------ */
/* Structural slices — what a pure function actually reads. Typed      */
/* minimally so the SAME function runs on a BlockScene, on a React Flow */
/* store's nodes/edges, or on any host's records that speak the         */
/* vocabulary. Matching the graph data types IS the adapter.            */
/* ------------------------------------------------------------------ */

export interface SceneEdgeEnds {
  source: string;
  target: string;
  /** `null` admitted here (only here) so React Flow's own `Edge[]`, whose
   *  handles are `string | null | undefined`, feeds these functions
   *  unmodified. */
  sourceHandle?: string | null;
  targetHandle?: string | null;
}

export interface ScenePortRef {
  nodeId: string;
  portId: string;
}


/* ------------------------------------------------------------------ */
/* The port vocabulary — asked for as RESOLVERS, never as fields, so a */
/* structural slice stays satisfiable by a BlockScene, a React Flow    */
/* store or a hand-built fixture with no adapter. `undefined` means    */
/* "unknown, no judgement" everywhere it appears.                       */
/* ------------------------------------------------------------------ */

/** Per-node port vocabulary, total: same contract as `findDanglingEdges`'s
 *  own `portsOf` (scene.ts:412-416) — omitted, only node existence is
 *  checked; `undefined` for a node means "unknown vocabulary, no port
 *  judgement for it." Reused verbatim rather than re-declared so the two
 *  call sites can never drift. */
export type PortsOf = (nodeId: string) => readonly string[] | undefined;

/**
 * A port's declared type vocabulary, or `undefined` for "unconstrained" —
 * same convention as `PortsOf` above. Shape adopted from Blockly
 * `ConnectionChecker.doTypeChecks` (Apache-2.0, fetched
 * `core/connection_checker.ts:203-219`): an optional ARRAY of accepted
 * tags per side, not a single type string, so a port can legitimately
 * accept more than one shape (a union-typed input). See this file's own
 * header for why maxGraph's `Multiplicity` was rejected as the donor.
 */
export type PortTypeOf = (ref: ScenePortRef) => readonly string[] | undefined;

/**
 * Which way a port faces: does it EMIT a value or RECEIVE one?
 *
 * This kit had no such vocabulary at all before 2026-09-18. `ScenePortRef`
 * is `{nodeId, portId}`, `PortsOf` returns bare NAMES, and `SceneNode` has
 * no ports field — so nothing in `src/scene/` could tell an output from an
 * input, and `validateConnection` consequently judged output→output LEGAL
 * (measured on `ValidityPreview`'s own fixture: dragging `num1/out` painted
 * `num2/out` available). See `docs/peps/0002-the-judge-owns-edge-orientation.md`.
 *
 * Declared as a RESOLVER, not a field, for the same reason `PortTypeOf` is:
 * a `LintScene` is a structural slice that a `BlockScene`, a React Flow
 * store, or a hand-built fixture all satisfy with no adapter, and adding a
 * required field to it would break that. `undefined` means "unknown
 * direction, no judgement" — the identical convention `PortsOf` and
 * `PortTypeOf` already document, so a caller that supplies nothing gets
 * byte-identical findings to before this existed.
 *
 * Vocabulary is the donor's: SystemSketch `PortPolarity = 'source' | 'sink'`
 * (`src/blocks/connections/connectionModel.ts:88`, opened). The donor DERIVES
 * it — `portPolarity(port.side, face)`, a function of the port's lane and
 * which face of the block is showing (`connectionRules.ts:175,183`) — which
 * this kit cannot do: it has neither lanes nor faces in the scene model. So
 * the answer is asked for rather than computed.
 */
export type PortDirection = "source" | "sink";

/** A port's direction, or `undefined` for "unknown" — see `PortDirection`. */
export type PortDirectionOf = (ref: ScenePortRef) => PortDirection | undefined;

/** Compatible iff... whatever this returns says so. Default is
 *  `typesIntersect` below; a caller may substitute equality, a hierarchy
 *  check, or anything else — this file mints no opinion beyond the list
 *  shape. */
export type TypeCompatible = (from: readonly string[], to: readonly string[]) => boolean;


/* ------------------------------------------------------------------ */
/* Linked-copy identity                                                 */
/* ------------------------------------------------------------------ */

/**
 * The data convention this module operates on. The split is the point
 * (Zach: "it's basically the data that is linked; appearance you have
 * much more flexibility"):
 *
 *   LINKED — shared by every occurrence of one definition:
 *     `name`          the definition's display name, and the linkage
 *                     trigger. NOT blind-copied by `setDefinitionData`;
 *                     it moves only through `commitDefinitionName`, the
 *                     one gesture whose job is to re-derive linkage.
 *                     (Donor parity: `sharedDefinitionProps` excludes
 *                     `title` too, donor 84-95 — raw spellings may
 *                     differ in whitespace, normalized names agree.)
 *     `linked`        the definition's content: port vocabulary, params,
 *                     docs — what the block IS.
 *     `expanded`      the EXPANDED view's appearance. Linked on purpose:
 *                     the expanded view is the function BODY, a function
 *                     gets one definition and all the call sites point
 *                     at that same definition. (Donor: `expandedSize` +
 *                     `expandedWeights` sit inside the shared props,
 *                     donor 91-92, while compact styling stays local.)
 *     `draftOrdinal`  present on a Draft definition; group-wide.
 *
 *   FREE — occurrence-local, never synced:
 *     `appearance`    the designated slot for per-occurrence styling
 *                     (compact view, size, accent, icon). The module
 *                     never reads it — it is named here so the split is
 *                     visible in the type, not just in a comment.
 *     …everything else a host keeps in `data`, plus `position`,
 *     `parentId`, and the node's edges. (Donor: "placement, outer
 *     wiring, current view and compact-view styling" stay local, donor
 *     674-676.)
 */
export type OccurrenceData = SceneData & {
  name?: string;
  draftOrdinal?: number;
  linked?: SceneData;
  expanded?: SceneData;
  appearance?: SceneData;
};

// src/scene/portEdgeCrossing.ts — "take a trace in, output a location out."
//
// Zach, 2026-09-18: "this line intersection logic with the port edge is
// super helpful and 100% we should implement pure functions for it as it's
// used again and again — kind of it should take a trace in, and output like
// a location out."
//
// ── WHAT IS ALREADY WRITTEN, AND WHY THIS FILE IS THIN ──────────────────
//
// The intersection math he is describing ALREADY EXISTS in this repo, and
// it already names his exact use case. `src/components/elbow/
// boundaryCrossing.ts` is a byte-for-byte copy of SystemSketch's
// `src/blocks/elbow/boundaryCrossing.ts` (copied 2026-09-17 under that
// file's "zero code edits" banner), and its own docstring lists, verbatim:
//
//     * a group or frame boundary port, for a cable that crosses in or out
//       of a collapsed group;
//
// It is Liang–Barsky, exact, handles diagonal segments, and documents its
// corner/boundary tie-breaks. Writing a second clipper here would be the
// "two derivations of one number is how they stop agreeing" failure
// `trace.routing.ts`'s `slantedAutomaticLead` header already warns about,
// and it would compete with a donor suite that was written against the
// donor, by the donor, before this repo existed.
//
// So this file writes NO intersection math. It is the SCENE-LAYER ADAPTER
// over that clipper, and it exists because the clipper's answer is not yet
// the answer a port needs. `BoundaryCrossing` reports `{point, side, t,
// distance}` where `t` is "position along the SEGMENT that crossed" — an
// artefact of which polyline segment happened to straddle the wall. What
// places a port is "how far along THAT WALL", which is a different number
// entirely and is nowhere in the donor. Converting one to the other, plus
// the two honesty facts below, is the whole job:
//
//   1. A ROUTE IS NOT ALWAYS A POLYLINE. `TraceRoute.points` is `null` for
//      a curved trace — its own doc: "`null` is not 'not computed yet' — it
//      is the honest answer". Zach asked for "best-effort from where the
//      wire or a straight line crosses the edge", so the chord stands in —
//      and `by: "chord"` says so in the result rather than letting a
//      caller mistake an approximation for a measurement.
//   2. THE INSET IS PART OF THE ANSWER. `boundaryCrossings` insets the box
//      before testing and returns a point on the INSET wall. Normalising
//      that point against the un-inset box silently pushes `t` outside
//      0..1. The normalisation below uses the same inset bounds that
//      produced the crossing.
//
// ── PROVENANCE ──────────────────────────────────────────────────────────
// Class (c) "ours, ad hoc" per docs/ALGORITHM-PROVENANCE.md: `alongSide` is
// a linear remap, not an algorithm, and no prior art is claimed for it. The
// clipper it stands on is class (a) and is cited above. Nothing here is
// from memory.
//
// Pure: no React, no DOM, no canvas engine — `src/scene/`'s rule. It
// imports `src/components/elbow/`, which is itself dependency-free by
// design ("must stay importable from a plain node script"), and types from
// `src/components/port.layout`. It WRITES nothing there.

import {
  boundaryCrossings,
  boundsOfRect,
  type BoundaryCrossing,
  type CrossingDirection,
  type ElbowBounds,
  type ElbowPoint,
  type ElbowRect,
  type ElbowSide,
} from "../components/elbow";
import type { BlockSide } from "../components/port.layout";

/* ------------------------------------------------------------------ */
/* Vocabulary                                                          */
/* ------------------------------------------------------------------ */

/**
 * `ElbowSide` and `BlockSide` are the SAME four strings — `'top' | 'right'
 * | 'bottom' | 'left'` in `elbow/geometry.ts`, `"left" | "right" | "top" |
 * "bottom"` in `port.layout.ts`. This assignment is the proof, checked by
 * the compiler on every build: add a fifth member to either and this line
 * stops compiling, which is the moment to write a translation table — not
 * before. No runtime mapping exists precisely because none is needed.
 */
const SIDES_AGREE: readonly BlockSide[] = ["top", "right", "bottom", "left"] satisfies readonly ElbowSide[];
void SIDES_AGREE;

/** A route that has real vertices, or a straight chord standing in for one
 *  that does not. Both spellings accepted so a caller never has to decide
 *  which shape this function wants. */
export interface TraceChord {
  start: ElbowPoint;
  end: ElbowPoint;
}

export type TraceGeometry = readonly ElbowPoint[] | TraceChord;

/** How the polyline under a location was obtained. Never inferred by the
 *  caller — `"chord"` means the real curve was never consulted. */
export type CrossingSource = "route" | "chord";

export interface ResolvedPolyline {
  points: readonly ElbowPoint[];
  by: CrossingSource;
}

/**
 * Where a derived port belongs on a box's wall. This is the shape the
 * rendering lane paints and the shape `boundary.ts` promotes with.
 *
 * `t` is the field this module exists to produce; everything else is
 * forwarded from the donor crossing unchanged.
 */
export interface PortEdgeLocation {
  /** Which wall. Same four strings as the elbow router's `ElbowSide`. */
  side: BlockSide;
  /**
   * How far along that wall, 0..1, in the wall's own READING direction:
   * left→right on `top`/`bottom`, top→bottom on `left`/`right`. That is
   * the same main-axis convention `blockPort.layout.ts`'s `railBoxFor`
   * lays its rails out in (its column-axis case runs `bandStart` →
   * `bandEnd` downward; its row-axis case runs `blockLeft` rightward), so
   * a `t` handed to a rail needs no flip.
   *
   * Clamped to 0..1. A degenerate wall (zero extent on its main axis)
   * yields 0 — the only finite answer, and not an error.
   */
  t: number;
  /** The crossing point itself, in the box's own space. On the INSET wall
   *  when an inset was given — see this file's header, fact 2. */
  point: ElbowPoint;
  /** Leaving the box, or entering it. The donor's own word. */
  direction: CrossingDirection;
  /** Arc length from the start of the path, so several crossings order. */
  distance: number;
  /** `"route"` — measured on the cable's real vertices. `"chord"` — the
   *  route had none (a Bezier: `TraceRoute.points === null`), so a
   *  straight line between its endpoints stood in. */
  by: CrossingSource;
}

export interface PortEdgeCrossingOptions {
  /** Grow (+) or shrink (−) the box before testing, in the box's units —
   *  forwarded verbatim to `boundaryCrossings`, and also applied to the
   *  bounds `t` is normalised against. */
  inset?: number;
  /** Tolerance for "on the boundary". Forwarded verbatim. */
  epsilon?: number;
}

/* ------------------------------------------------------------------ */
/* The two numbers this file actually computes                         */
/* ------------------------------------------------------------------ */

function insetBounds(bounds: ElbowBounds, amount: number): ElbowBounds {
  if (!amount) return bounds;
  const [minX, minY, maxX, maxY] = bounds;
  return [minX - amount, minY - amount, maxX + amount, maxY + amount];
}

/**
 * The remap the donor does not do: a point known to sit on `side` of
 * `bounds`, as a 0..1 position ALONG that side.
 *
 * WHY this is not `BoundaryCrossing.t`: the donor's `t` is "position along
 * the polyline SEGMENT that crossed", so it moves when the cable is
 * re-routed with a different number of bends even though the cable still
 * meets the wall in exactly the same place. A port placed from that number
 * would slide for no visible reason. This one depends only on the geometry
 * of the meeting.
 *
 * Exported because the rendering lane needs it standalone: given a port
 * already placed at a point, it answers "where on the rail".
 */
export function alongSide(bounds: ElbowBounds, side: BlockSide, point: ElbowPoint): number {
  const [minX, minY, maxX, maxY] = bounds;
  const horizontal = side === "top" || side === "bottom";
  const span = horizontal ? maxX - minX : maxY - minY;
  // A wall with no length has no "along" — 0 is the only finite answer,
  // and a zero-extent box is a legal (if silly) input, not a throw.
  if (!(span > 0)) return 0;
  const raw = horizontal ? (point.x - minX) / span : (point.y - minY) / span;
  return raw < 0 ? 0 : raw > 1 ? 1 : raw;
}

/**
 * A route's polyline, or the honest chord standing in for it.
 *
 * `route.points` is `TraceRoute.points` — `null` for `curved`, by that
 * type's own deliberate contract. `chord` is where the cable actually
 * starts and ends, which `TraceRoute` does not carry, so the caller
 * supplies it.
 */
export function tracePolyline(
  route: { readonly points: readonly ElbowPoint[] | null } | null | undefined,
  chord: TraceChord,
): ResolvedPolyline {
  const points = route?.points;
  if (points && points.length >= 2) return { points, by: "route" };
  return { points: [chord.start, chord.end], by: "chord" };
}

function normalizeGeometry(geometry: TraceGeometry): ResolvedPolyline {
  if (Array.isArray(geometry)) {
    const points = geometry as readonly ElbowPoint[];
    // Fewer than two points is not a path — there is nothing to cross
    // with, and inventing a second point would be a guess.
    return { points, by: "route" };
  }
  const chord = geometry as TraceChord;
  return { points: [chord.start, chord.end], by: "chord" };
}

/* ------------------------------------------------------------------ */
/* THE function — trace in, location out                               */
/* ------------------------------------------------------------------ */

/**
 * Every place `geometry` meets `box`'s boundary, as port-edge locations, in
 * path order. Thin by design: `boundaryCrossings` finds them (Liang–Barsky,
 * donor-verbatim), this adds `side`-relative `t` and the `by` provenance.
 *
 * Total: a path that misses the box entirely, a path wholly inside, or a
 * path with fewer than two points all yield `[]` — the honest nothing.
 */
export function portEdgeCrossings(
  geometry: TraceGeometry,
  box: ElbowRect,
  options: PortEdgeCrossingOptions = {},
): PortEdgeLocation[] {
  const { points, by } = normalizeGeometry(geometry);
  if (points.length < 2) return [];
  const bounds = insetBounds(boundsOfRect(box), options.inset ?? 0);
  const crossings: BoundaryCrossing[] = boundaryCrossings(points, box, options);
  return crossings.map((crossing) => ({
    side: crossing.side satisfies ElbowSide as BlockSide,
    t: alongSide(bounds, crossing.side, crossing.point),
    point: crossing.point,
    direction: crossing.direction,
    distance: crossing.distance,
    by,
  }));
}

export interface PortEdgeLocationOptions extends PortEdgeCrossingOptions {
  /**
   * Which crossing a port is wanted for. Default `"exit"` — the cable
   * LEAVING the box is where a derived boundary port belongs, which is the
   * donor's own `firstExit` framing ("the first place the path leaves the
   * box — where a derived port belongs").
   *
   * `"enter"` takes the LAST entry rather than the first, matching the
   * donor's `lastEntry`: a cable that weaves in and out finally settles
   * inside on its last crossing, and that is the one a port stands for.
   */
  direction?: CrossingDirection;
}

/**
 * "Take a trace in, output a location out" — the single call Zach named.
 *
 * Returns `null` when the path never crosses in the asked direction. It
 * does NOT silently answer with the other direction: a caller that wanted
 * an exit and got an entry would place a port on the wrong wall, and
 * "there is no exit" is a fact worth returning.
 */
export function portEdgeLocation(
  geometry: TraceGeometry,
  box: ElbowRect,
  options: PortEdgeLocationOptions = {},
): PortEdgeLocation | null {
  const want = options.direction ?? "exit";
  const all = portEdgeCrossings(geometry, box, options).filter((hit) => hit.direction === want);
  if (all.length === 0) return null;
  return want === "exit" ? all[0] : all[all.length - 1];
}

/**
 * One cable against several boxes — a block inside a region inside a frame.
 * Mirrors the donor's `firstExitPerBox` (which this deliberately does NOT
 * call: that one returns `BoundaryCrossing`, and re-normalising its `t`
 * afterwards would need the inset bounds recomputed per box anyway).
 * Boxes with no crossing in the asked direction are absent from the map, so
 * one pass derives a port per level.
 */
export function portEdgeLocationPerBox<Key extends string | number>(
  geometry: TraceGeometry,
  boxes: ReadonlyArray<{ key: Key; box: ElbowRect }>,
  options: PortEdgeLocationOptions = {},
): Map<Key, PortEdgeLocation> {
  const found = new Map<Key, PortEdgeLocation>();
  for (const { key, box } of boxes) {
    const hit = portEdgeLocation(geometry, box, options);
    if (hit) found.set(key, hit);
  }
  return found;
}

// src/scene/region.loop.ts — the Loop PRESET: for / while, as data over the
// generic Region (docs/CONTROL-FLOW-PLAN.md lane B).
//
// There is no `LoopRegion` component here, and there deliberately never
// will be one — the same ruling `components/block.value.tsx:1-45` already
// carries ("a PRESET of components that already exist, not a component of
// its own"). `hosts/nodeViews.tsx`'s `region` case already draws the corner
// block from `data.ports` and the body from `bodyChildrenOf`; a loop is
// that renderer handed three fields. DP - Loop states it from the other
// side: "**a loop is a Region with one arm, plus one cable that comes
// back**… one Loop component with two header contracts rather than a For
// component and a While component."
//
// So everything below is a pure factory over the scene record — no React,
// no DOM, no layout. What it encodes is the GRAMMAR:
//
//   • "everything is a block" — the node these factories mint is ONE
//     `type: "region"` node whose `data.ports` land on a real `BlockPort`
//     in the frame's corner. A loop's `Iterable` is resolved by the exact
//     `[data-block-id]` → `[data-port-id]` walk any other block's port is.
//   • "never mix data and control lines" — nothing here mints a control
//     cable. The only edge factory is `carriedValueEdge`, and what it makes
//     is an ordinary DATA cable that is merely one turn late. `break` is a
//     mark (`HostNodeData.marks`, B5), the loop's arm is containment, and
//     "loop back" is a routing choice, not an edge kind.

import { REGION_NODE_TYPE } from "./region";
import type { ScenePosition, SceneEdge, SceneNode } from "./scene";
import type { WireStyleData } from "./sceneWires";
import type { HostNodeData } from "../hosts/hostScene";
import type { RegionView } from "../hosts/regionScene";

/**
 * The header's port ids — and its port LABELS, because they are the same
 * string.
 *
 * WHY the id IS the type and there is no name anywhere near it (DP - Loop;
 * donor `/home/bam/systemsketch/src/loop/loopModel.ts:55-70`, "A type and
 * nothing else. You do not NAME these — the collection's name lives on
 * whatever produces it, and the element has no name until a Block's port
 * gives it one. What the header can say is what KIND of thing crosses it,
 * so the inlet reads `Iterable` and the outlet reads `Iter`"): a header
 * port named `items` would be claiming to know what the collection is
 * called, which is the producer's business. `edgeSpecsOf` (nodeViews.tsx)
 * builds each item as `{ id, label: id }`, so writing the type here is
 * literally what paints it.
 */
export const LOOP_PORT_IDS = {
  /** `for`: the collection, consumed once at entry. */
  iterable: "Iterable",
  /** `for`: the element the header emits, once per turn. */
  iter: "Iter",
  /** `while`: the condition, re-evaluated after every pass. */
  bool: "Bool",
} as const;

export interface LoopNodeOptions {
  id: string;
  /** The corner block's header. Defaults per loop kind. */
  name?: string;
  /** Top-level: canvas space. With `parentId`: the parent's space. */
  position: ScenePosition;
  /** The FRAME's width/height — the corner hugs at `REGION_CORNER_WIDTH_PX`. */
  w?: number;
  h?: number;
  /** Default `"expanded"` (the P1 frame). `"opaque"` is the P5 card. */
  view?: RegionView;
  /** A chip in the corner block's header — the donor's `turn`, e.g.
   *  `"iteration 3 of 7"`. */
  badge?: string;
  /** A loop nested in another region or arm. */
  parentId?: string;
}

const DEFAULT_W = 400;
const DEFAULT_H = 300;

function loopNode(options: LoopNodeOptions, loop: "for" | "while", defaultName: string): SceneNode<HostNodeData> {
  const { id, name = defaultName, position, w = DEFAULT_W, h = DEFAULT_H, view = "expanded", badge, parentId } = options;
  return {
    id,
    type: REGION_NODE_TYPE,
    position,
    // WHY `definitionId` is not merely unset but unsettable from here: a
    // region is ISOLATED (`scene/region.ts:19-26`, the ruling lane A
    // implements) — it is a scope, not an occurrence of a shared
    // definition, so a loop that carried one would be claiming every loop
    // with that id is the same loop. `loop.test.ts` asserts the absence.
    ...(parentId === undefined ? null : { parentId }),
    data: {
      name,
      region: { kind: "loop", loop, view },
      ports: loop === "for" ? forPorts() : whilePorts(),
      w,
      h,
      ...(badge === undefined ? null : { badge }),
    },
  };
}

/** `for item in iterable`: the collection in on the left wall, the element
 *  out on the right. Both are real ports carrying ordinary cables — the
 *  element's cable is SOLID (donor loopModel.ts:15-20: dotted stays
 *  reserved for the back cable, and *this* turn's element is ordinary
 *  data). */
function forPorts(): HostNodeData["ports"] {
  return { left: [LOOP_PORT_IDS.iterable], right: [LOOP_PORT_IDS.iter] };
}

/**
 * `while condition`: a `Bool` inlet and NOTHING on the right wall.
 *
 * WHY the missing right wall is the design and not an omission (DP - Loop's
 * own header table, "Header output — for: typed `Iter` item outlet; while:
 * **none — the body owns the values it carries**"): a `while` is not a
 * renamed `for`. An iterable is consumed at entry and the header can
 * therefore hand out this turn's element; a condition is re-evaluated after
 * each pass and produces no element at all, so an outlet would have to emit
 * something the construct does not have. The tempting alternative — giving
 * `while` an `Iter` too "for symmetry" — mints a port with no value behind
 * it, which is exactly the kind of drawn-but-meaningless dot the typed
 * unnamed header exists to avoid.
 */
function whilePorts(): HostNodeData["ports"] {
  return { left: [LOOP_PORT_IDS.bool] };
}

/** `for other in others:` — `Iterable` in, `Iter` out, on the corner block. */
export function forLoopNode(options: LoopNodeOptions): SceneNode<HostNodeData> {
  return loopNode(options, "for", "For Loop");
}

/** `while condition:` — `Bool` in, no item outlet. */
export function whileLoopNode(options: LoopNodeOptions): SceneNode<HostNodeData> {
  return loopNode(options, "while", "While Loop");
}

export interface CarriedValueEdgeOptions {
  id: string;
  /** The block that carries the value: the cable leaves it and re-enters
   *  it, which is what makes the state ITS state. */
  nodeId: string;
  /** The port it leaves from (an output). */
  from: string;
  /** The port it comes back into (an input). */
  to: string;
  /** What produced the value before the first turn — spelled into the pill
   *  as `z⁻¹ = estimate()`. Omitted = the bare derived `z⁻¹`. */
  seed?: string;
}

/**
 * The carried value: `merge/Pose` → `merge/pose`, one turn late.
 *
 * WHY this is a DATA cable and not a control line — the load-bearing half
 * of the loop grammar (DP - Loop, "The carried value, and the `z⁻¹` edge"):
 * what travels here is a *value*, and the only thing that distinguishes it
 * from any other cable is WHEN it is read. So `variant: "delayed"` (the
 * dotted paint `trace.layout.ts:72-85` already ships) says "next
 * iteration", and no second kind of line is invented. The naive alternative
 * — a "loop back" control wire — would put control flow on a cable, which
 * is the one thing this language never does: control here is the
 * containment and the marks.
 *
 * WHY `routing: "elbow"` rides along: "go to the end first, then loop back"
 * is *format, not semantics* (DP - Loop) — default routing of the back
 * cable is right edge, bottom lane, back, which is exactly what the elbow
 * router with keep-outs produces once the cable is told to be orthogonal.
 * A whiteboard may bend it; nothing about the meaning changes if it does.
 *
 * WHY there is no `badge` when no seed is given: `sceneWires` derives
 * `"z⁻¹"` for every delayed edge that names none (plan Q7, "always draw the
 * pill"). Writing `badge: "z⁻¹"` here would author the derived value, and
 * the first change to the derivation would then silently skip every edge
 * this factory made.
 */
export function carriedValueEdge(options: CarriedValueEdgeOptions): SceneEdge<WireStyleData> {
  const { id, nodeId, from, to, seed } = options;
  return {
    id,
    source: nodeId,
    sourceHandle: from,
    target: nodeId,
    targetHandle: to,
    data: {
      variant: "delayed",
      routing: "elbow",
      ...(seed === undefined ? null : { badge: `z⁻¹ = ${seed}` }),
    },
  };
}

// src/scene/region.ts — Region as a NODE KIND, plus the three nesting
// queries the grouping algebra needs and `scene.ts` does not yet have.
//
// ── ZACH'S RULING, IMPLEMENTED LITERALLY ────────────────────────────────
//
// 2026-09-18, on whether a region is a Block preset or its own thing:
// "100% its a node. its just a unique type of node that is different from
// block." His diagram put `Block` and `Region` both under one `Node<T>` —
// "one class, ports either way" — and noted React Flow says the same
// (everything is a node or an edge).
//
// So a Region needs NO change to `SceneNode`. `type?: string` is already
// "host-interpreted kind (React Flow's `nodeTypes` key)" and already
// exactly the field React Flow keys `nodeTypes` off. A region is a
// `SceneNode` whose `type` is `REGION_NODE_TYPE`, carrying ports like any
// other node. That is the whole of it — `REGION_NODE_TYPE` below is a
// constant so the string is spelled once, not a new concept.
//
// AND REGIONS ARE ISOLATED. Zach: "100% region is isolated. Regions in code
// are not linked, so our regions shouldn't be either! If you want it to be
// linked then put the region inside a function and then link that
// function." A region node therefore never carries a `definitionId`, and
// `collapse.ts` never mints one. `linking.ts` is the machinery for linked
// occurrences; a region simply does not participate in it. `regionOf`
// below is the only "which region owns this" lookup, and it walks
// `parentId` — containment — never a definition group.
//
// ── WHY THESE THREE QUERIES LIVE HERE AND NOT IN scene.ts ───────────────
//
// `scene.ts` is frozen for this lane (write set: "do not edit scene.ts —
// extend from a new file"). Each of the three is a strict extension, and
// each has an in-repo predecessor that is PRIVATE to its own module — the
// duplication is pre-existing, and this file is where it stops growing:
//
//   `descendantsOf`    — `linking.ts`'s `deleteNode` grows the identical
//                        doomed-set fixpoint inline (its `for (;;)` loop),
//                        because "containment is ownership". Same walk,
//                        made public, made cycle-safe.
//   `absolutePosition` — nobody has needed it yet, because nothing before
//                        this lane RE-PARENTED a node. `SceneNode.position`
//                        is documented as living "in the parent's
//                        coordinate space when `parentId` is set (React
//                        Flow's sub-flow rule, kept)", so the moment
//                        `parentId` changes, `position` must be rebased or
//                        the node teleports. This is the function that
//                        makes collapse/dissolve position-exact.
//   `selectionRoots`   — the set a re-parent may touch. Re-parenting a node
//                        that is already inside another selected node would
//                        flatten authored nesting; only the roots move.
//
// Pure: no React, no DOM, no canvas engine.

import type { BlockScene, SceneData, SceneNode, ScenePosition } from "./scene";

/* ------------------------------------------------------------------ */
/* The kind                                                            */
/* ------------------------------------------------------------------ */

/** `SceneNode.type` for a region. One spelling, in one place. */
export const REGION_NODE_TYPE = "region";

/** Is this node a region? A total predicate — `type` is optional, and an
 *  absent `type` is a block-ish node, not an error. */
export function isRegion(node: { type?: string }): boolean {
  return node.type === REGION_NODE_TYPE;
}

/**
 * A box in the scene's own coordinate space. Supplied by a RESOLVER, never
 * read off the record: `SceneNode` carries `position` and deliberately no
 * size (a size is measured by whoever paints, and the scene kit does not
 * paint). Same shape as the elbow router's `ElbowRect` so a box travels
 * into `portEdgeCrossing.ts` with no conversion.
 *
 * Injected the way `findDanglingEdges` takes `portsOf` (scene.ts) and for
 * the same stated reason: per-node total, and `undefined` means "unknown",
 * never "empty".
 */
export type BoxOf = (nodeId: string) => { x: number; y: number; w: number; h: number } | undefined;

/* ------------------------------------------------------------------ */
/* Nesting                                                             */
/* ------------------------------------------------------------------ */

/**
 * Every node transitively inside `seeds`, the seeds included, in scene
 * order. The fixpoint `linking.ts`'s `deleteNode` runs inline, made public
 * and made total: a `parentId` cycle (which the record's contract forbids
 * but a malformed document can still contain) terminates instead of
 * spinning, because a node already in the set is never re-added.
 *
 * Seeds naming nodes that do not exist are simply absent from the result —
 * the honest smaller answer, `dependencyGraph`'s own policy in scene.ts.
 */
export function descendantsOf<N extends SceneData>(
  scene: { nodes: readonly SceneNode<N>[] },
  seeds: Iterable<string>,
): Set<string> {
  const known = new Set(scene.nodes.map((node) => node.id));
  const inside = new Set<string>();
  for (const id of seeds) if (known.has(id)) inside.add(id);
  for (;;) {
    const grown = scene.nodes.filter(
      (node) => !inside.has(node.id) && node.parentId !== undefined && inside.has(node.parentId),
    );
    if (grown.length === 0) break;
    for (const node of grown) inside.add(node.id);
  }
  return inside;
}

/**
 * The members of `inside` whose own parent is NOT in `inside` — the only
 * nodes a re-parent may touch.
 *
 * WHY it matters: selecting a block AND its child and collapsing both must
 * not make the child a sibling of its own parent. Authored nesting is a
 * fact the selection did not ask to change; only the outermost members move
 * into the new container, and everything under them comes along by
 * containment. Scene order.
 */
export function selectionRoots<N extends SceneData>(
  scene: { nodes: readonly SceneNode<N>[] },
  inside: ReadonlySet<string>,
): SceneNode<N>[] {
  return scene.nodes.filter(
    (node) => inside.has(node.id) && (node.parentId === undefined || !inside.has(node.parentId)),
  );
}

/**
 * A node's position in the SCENE's space, with every ancestor's offset
 * folded in. `undefined` for an unknown node.
 *
 * Total against a malformed `parentId` cycle: the walk stops the first time
 * it revisits a node, returning what it summed so far rather than looping.
 * A `parentId` naming a node that does not exist ends the walk too — the
 * same "unknown means stop, not throw" policy as everywhere else here.
 */
export function absolutePosition<N extends SceneData>(
  scene: { nodes: readonly SceneNode<N>[] },
  nodeId: string,
): ScenePosition | undefined {
  const byId = new Map(scene.nodes.map((node) => [node.id, node]));
  const start = byId.get(nodeId);
  if (!start) return undefined;
  let x = 0;
  let y = 0;
  const seen = new Set<string>();
  let node: SceneNode<N> | undefined = start;
  while (node && !seen.has(node.id)) {
    seen.add(node.id);
    x += node.position.x;
    y += node.position.y;
    node = node.parentId === undefined ? undefined : byId.get(node.parentId);
  }
  return { x, y };
}

/**
 * The nearest ancestor of `nodeId` that is a region, or `undefined`. Walks
 * `parentId` — CONTAINMENT, never a definition group (see this file's
 * header on isolation). Cycle-safe by the same visited set.
 */
export function regionOf<N extends SceneData>(
  scene: { nodes: readonly SceneNode<N>[] },
  nodeId: string,
): SceneNode<N> | undefined {
  const byId = new Map(scene.nodes.map((node) => [node.id, node]));
  const seen = new Set<string>([nodeId]);
  let parentId = byId.get(nodeId)?.parentId;
  while (parentId !== undefined && !seen.has(parentId)) {
    seen.add(parentId);
    const parent = byId.get(parentId);
    if (!parent) return undefined;
    if (isRegion(parent)) return parent;
    parentId = parent.parentId;
  }
  return undefined;
}

/**
 * The `parentId` chain from `nodeId` outward, nearest first, NOT including
 * `nodeId` itself. The path `boundaryWiring.ts` walks to find which
 * containers a cable would have to punch through. Cycle-safe.
 */
export function ancestorsOf<N extends SceneData>(
  scene: { nodes: readonly SceneNode<N>[] },
  nodeId: string,
): string[] {
  const byId = new Map(scene.nodes.map((node) => [node.id, node]));
  const chain: string[] = [];
  const seen = new Set<string>([nodeId]);
  let parentId = byId.get(nodeId)?.parentId;
  while (parentId !== undefined && !seen.has(parentId) && byId.has(parentId)) {
    seen.add(parentId);
    chain.push(parentId);
    parentId = byId.get(parentId)!.parentId;
  }
  return chain;
}

/**
 * The bounding box of a set of nodes in SCENE space, from an injected
 * `boxOf`. `undefined` when no member resolves — a caller then has no
 * geometry and must say so rather than invent a zero box.
 *
 * Members whose box is unknown still contribute their `absolutePosition` as
 * a zero-size point, so a partially-measured scene still yields a box that
 * contains everything it knows about. That is a deliberate widening: a
 * region drawn slightly too large is a cosmetic problem, one drawn too
 * small clips a member.
 */
export function boundsOfNodes<N extends SceneData>(
  scene: { nodes: readonly SceneNode<N>[] },
  nodeIds: Iterable<string>,
  boxOf?: BoxOf,
): { x: number; y: number; w: number; h: number } | undefined {
  let minX = Number.POSITIVE_INFINITY;
  let minY = Number.POSITIVE_INFINITY;
  let maxX = Number.NEGATIVE_INFINITY;
  let maxY = Number.NEGATIVE_INFINITY;
  let any = false;
  for (const id of nodeIds) {
    const at = absolutePosition(scene, id);
    if (!at) continue;
    const box = boxOf?.(id);
    const w = box?.w ?? 0;
    const h = box?.h ?? 0;
    any = true;
    minX = Math.min(minX, at.x);
    minY = Math.min(minY, at.y);
    maxX = Math.max(maxX, at.x + w);
    maxY = Math.max(maxY, at.y + h);
  }
  if (!any) return undefined;
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}

/** Narrowing helper: every region in the scene, in scene order. */
export function regionsOf<N extends SceneData, E extends SceneData>(scene: BlockScene<N, E>): SceneNode<N>[] {
  return scene.nodes.filter(isRegion);
}

// src/scene/regionView.ts — the OPAQUE view of a region as a PROJECTION over
// the scene, never a mutation of it. docs/CONTROL-FLOW-PLAN.md §2.B/§3.4,
// lane E. Signatures frozen by `regionView.test.ts` (off-limits to builders).
//
// ── WHY A PROJECTION, WHEN collapse.ts MUTATES ──────────────────────────
// `collapseToRegion` (collapse.ts) MINTS a region around a loose selection
// and splits every crossing edge through a promoted port; that is a
// document edit and docs/peps/0003 records why. The opaque/expanded TOGGLE
// is a different operation on a region that already exists: Zach's P1
// ruling is that in the expanded view "data cables run straight from
// outside into the calls inside an arm" (V1, picked 2026-09-02, repeated
// 2026-09-18) — so the expanded document has DIRECT crossing edges, and the
// opaque card is what those same edges look like when their inside end is
// hidden. Flipping a view must therefore change ONE field
// (`data.region.view`) and zero edges; positions and ids are untouched by
// construction, which `hosts/regionScene.test.ts` asserts as referential
// identity. The QUERY half of collapse.ts (`classifyBoundary` +
// `promoteBoundary`, both pure, both non-mutating) is exactly what this
// module reuses — one port vocabulary, no second implementation. The
// MUTATING twin this file deliberately never calls is `collapse.ts:242-262`
// — the `scene.edges.map` that re-points every crossing edge and the loop
// under it that pushes one interior stub per promoted port. The re-pointing
// rule below is that same rule applied to a COPY thrown away on the next
// render, instead of written back into the document.
//
// Pure: no React, no DOM, no canvas engine.

import { classifyBoundary, dagPolarityPolicy, promoteBoundary, type PromotedPort, type PromotionPolicy } from "./boundary";
import { hiddenSummary, type HiddenSummary } from "./controlFlow";
import type { PortDirectionOf, PortTypeOf } from "./lint";
import { ancestorsOf, descendantsOf } from "./region";
import { portKey, type BlockScene, type SceneData, type SceneEdge, type SceneNode, type ScenePortRef } from "./scene";

export interface ProjectOpaqueOptions<N extends SceneData = SceneData> {
  /** Which region nodes are currently opaque. Host vocabulary is injected,
   *  never read off `data` here — the same "no vocabulary supplied, no
   *  opinion" convention `lint.ts`'s resolvers use. */
  isOpaque: (node: SceneNode<N>) => boolean;
  /** Polarity for `promoteBoundary`'s side decision (its `dagPolarityPolicy`). */
  directionOf?: PortDirectionOf;
  typeOf?: PortTypeOf;
  /** Names a promoted port. Default `portKey(inner.nodeId, inner.portId)`
   *  — collapse.ts's own default, so a card and a collapse agree. */
  mintPortId?: (inner: ScenePortRef) => string;
}

/** One opaque region's card, as data: its promoted ports and what it hides. */
export interface OpaqueRegionView {
  regionId: string;
  ports: PromotedPort[];
  hidden: HiddenSummary;
}

export interface RegionProjection<N extends SceneData = SceneData, E extends SceneData = SceneData> {
  /** THE SAME array object as `scene.nodes` — a projection never touches a node. */
  nodes: SceneNode<N>[];
  /**
   * The edges a host paints. When NO region is opaque this is `scene.edges`
   * itself (referential identity — the expanded view costs nothing).
   * Otherwise, per OUTERMOST opaque region R (a region hidden inside another
   * opaque region gets no treatment of its own):
   *   - an edge with exactly one end inside R is re-pointed: that end
   *     becomes `{R, promotedPortId}`; `id`, `data` and the other end are
   *     untouched (a new edge OBJECT, since the end changed);
   *   - an edge with both ends inside R (`interior`) is dropped;
   *   - an edge between R itself and something inside R (`port-inner`) is
   *     dropped — the region's own `Iter`-style cable is private wiring;
   *   - an edge touching R's own ports from outside (`port-outer`) is the
   *     SAME object;
   *   - an edge whose two ends are inside two DIFFERENT outermost opaque
   *     regions is re-pointed at both ends.
   * Scene order preserved.
   */
  edges: SceneEdge<E>[];
  /** One entry per outermost opaque region, scene order. */
  regions: OpaqueRegionView[];
}

/**
 * WHY the promotion policy here reads the INNER endpoint and not the outer
 * one `dagPolarityPolicy` reads.
 *
 * A projection is not a collapse. `collapseToRegion` promotes a port for a
 * selection that has no container yet, so the only polarity it can trust is
 * the OUTSIDE end's, inverted — Zach's stated v1 ("if it's connecting to an
 * input port of an outside member then it should go out the right side of
 * the header"). Here the inside end is a real port on a real node that is
 * still in the document: the card's port IS that inner port, re-seated on
 * the region's wall, so its polarity is the inner port's polarity, read
 * directly rather than inferred by inverting its partner's. Under a
 * well-formed edge the two readings agree; when they disagree the direct
 * read is the one that is not a heuristic, and `regionView.test.ts` pins
 * exactly that case (`src/pose → merge/pose`, where the resolver calls both
 * ends sinks).
 *
 * `dagPolarityPolicy` still supplies the answer — and the `seat`/`band`
 * choice, and the `by: "gesture"` honesty — whenever the inner port states
 * no direction at all. One policy, one fallback, no second spelling of the
 * side mapping: `source → right`, `sink → left`, which is
 * `port.layout.ts`'s `portSideForDirection` in the source/sink vocabulary
 * `boundary.ts`'s `PromotionDecision` header already maps it to.
 */
const innerPolarityPolicy: PromotionPolicy = (input) => {
  const fallback = dagPolarityPolicy(input);
  const stated = input.inner.portId === "" ? undefined : input.directionOf?.(input.inner);
  if (stated === undefined) return fallback;
  return { ...fallback, direction: stated, side: stated === "source" ? "right" : "left", by: "polarity" };
};

export function projectOpaqueRegions<N extends SceneData, E extends SceneData>(
  scene: BlockScene<N, E>,
  options: ProjectOpaqueOptions<N>,
): RegionProjection<N, E> {
  const mintPortId = options.mintPortId ?? ((inner: ScenePortRef) => portKey(inner.nodeId, inner.portId));

  // WHY only the OUTERMOST opaque region gets a card: a region hidden
  // inside another opaque region is not on screen at all, so promoting its
  // ports would mint a seat nothing can paint and re-point an edge at a
  // node the viewer cannot see. The outer card already stands for
  // everything under it — `hiddenSummary` counts the nested region as one
  // of the blocks it hides. `ancestorsOf` walks containment (`parentId`),
  // which is the only nesting a region has (regions are isolated — they
  // never carry a `definitionId`).
  const opaqueIds = scene.nodes.filter((node) => options.isOpaque(node)).map((node) => node.id);
  const opaque = new Set(opaqueIds);
  const outermost = opaqueIds.filter((id) => !ancestorsOf(scene, id).some((ancestor) => opaque.has(ancestor)));

  // Nothing opaque: the expanded view costs NOTHING — the very arrays the
  // caller passed in come back, so a host's `useMemo`/`===` guards never
  // see a change and no render is provoked by asking the question.
  if (outermost.length === 0) return { nodes: scene.nodes, edges: scene.edges, regions: [] };

  const regions: OpaqueRegionView[] = [];
  /** node id → the outermost opaque region that hides it. Built ONCE. */
  const ownerOf = new Map<string, string>();
  /** region id → (portKey of the inner endpoint → the promoted port). */
  const portsOfRegion = new Map<string, Map<string, PromotedPort>>();

  for (const regionId of outermost) {
    const report = classifyBoundary(scene, { containerId: regionId });
    const { ports } = promoteBoundary(report, {
      policy: innerPolarityPolicy,
      directionOf: options.directionOf,
      typeOf: options.typeOf,
      // `promoteBoundary` hands its minter `{inner, index, decision}`; this
      // module's own seam takes the endpoint alone, because the DEFAULT has
      // to be `portKey(inner)` — the same id `collapse.ts:197` mints — so a
      // card and a collapse of the same region name the same port.
      mintPortId: ({ inner }) => mintPortId(inner),
    });
    portsOfRegion.set(regionId, new Map(ports.map((port) => [portKey(port.inner.nodeId, port.inner.portId), port])));
    regions.push({ regionId, ports, hidden: hiddenSummary(scene, regionId) });
    // The seeds include the region itself; a region never owns ITSELF (its
    // own ports are the boundary, which is what `port-outer`/`port-inner`
    // separate). Outermost regions are disjoint by construction, so the
    // first writer is the only writer.
    for (const id of descendantsOf(scene, [regionId])) if (id !== regionId) ownerOf.set(id, regionId);
  }

  /** The promoted port id an owned endpoint is re-pointed at. */
  const promotedIdFor = (regionId: string, nodeId: string, handle: string | undefined): string | undefined =>
    portsOfRegion.get(regionId)?.get(portKey(nodeId, handle ?? ""))?.id;

  const edges: SceneEdge<E>[] = [];
  for (const edge of scene.edges) {
    const sourceOwner = ownerOf.get(edge.source);
    const targetOwner = ownerOf.get(edge.target);
    // Neither end is hidden: `port-outer` and `exterior` both land here and
    // both are the SAME OBJECT — a projection that copied them would make
    // every host's edge memo churn for edges nothing happened to.
    if (sourceOwner === undefined && targetOwner === undefined) {
      edges.push(edge);
      continue;
    }
    // `interior` — "from inside member to inside member those can all be
    // hidden" (boundary.ts's quoted rule).
    if (sourceOwner !== undefined && sourceOwner === targetOwner) continue;
    // `port-inner` — the region's own port wired to something inside it (a
    // loop's `Iter` cable). Private wiring, never re-pointed: promoting it
    // would draw the region's own port feeding the region's own port, and
    // "never mix data and control lines" starts with not inventing a cable
    // that the expanded document does not contain.
    if (sourceOwner !== undefined && edge.target === sourceOwner) continue;
    if (targetOwner !== undefined && edge.source === targetOwner) continue;

    // A crossing edge: the hidden end moves to the card's promoted port.
    // `id`, `data` and the end that is still visible are untouched — that
    // is the whole trick, and it is the same one `collapse.ts:242-262`
    // plays, minus the document write.
    let next = edge;
    if (sourceOwner !== undefined) {
      const portId = promotedIdFor(sourceOwner, edge.source, edge.sourceHandle);
      if (portId !== undefined) next = { ...next, source: sourceOwner, sourceHandle: portId };
    }
    if (targetOwner !== undefined) {
      const portId = promotedIdFor(targetOwner, edge.target, edge.targetHandle);
      if (portId !== undefined) next = { ...next, target: targetOwner, targetHandle: portId };
    }
    edges.push(next);
  }

  // `scene.nodes` ITSELF: the one sentence this module exists to make true.
  return { nodes: scene.nodes, edges, regions };
}

// src/scene/scene.ts — the scene kit: ONE record for "how the components
// relate and talk to each other", and pure functions over it. The view kit
// (src/components/) stays props-in DOM-out and knows nothing about this
// file; a host reads a scene and passes props, a pure function reads a
// scene and returns data (docs/SCENE-KIT.md).
//
// The vocabulary is borrowed from React Flow DELIBERATELY and closely —
// node/edge, source/target, sourceHandle/targetHandle, position, data,
// parentId — because the names carry the domain (Zach, 2026-09-17: "we are
// borrowing the domain vocabulary which carries a lot in it"). Borrowed is
// falsifiable, not a vibe: `scene.reactflow.test.ts` proves a
// `SceneNode`/`SceneEdge` assigns to `@xyflow/react`'s published
// `Node`/`Edge` types with no cast. This file still imports NOTHING — no
// React, no tldraw, no `@xyflow/react`, not even their types. Matching the
// shape without taking the dependency is the whole point: adapting into
// React Flow is then a type-level identity, and adapting into tldraw is a
// field map, with every pure function below working unchanged on either.
//
// Before this file there were three partial scene models that did not know
// about each other: `wiring.ts`'s `Wire` (edges), `blockMembers.tsx`'s
// `BlockMember` (nesting AND placement fused), and `portLane.ts`'s LCS
// reconcile (port identity across an edit — a diff algorithm standing in
// for the owner identity never had). This record is the owner. `wiring.ts`
// is absorbed (its model half deleted, its paint half kept —
// see `sceneWires.ts`); the other two are documented tenants for later.

// The scene's own vocabulary now has one declaration site, `./model` — see
// that file's header for the rule about what belongs there. Re-exported from
// here so every existing `from "./scene"` import keeps resolving, and so a
// reader who opens this file still meets the record before the functions
// over it.
import type {
  BlockScene,
  SceneData,
  SceneEdge,
  SceneEdgeEnds,
  SceneNode,
  ScenePortRef,
  ScenePosition,
} from "./model";
export type {
  BlockScene,
  SceneData,
  SceneEdge,
  SceneEdgeEnds,
  SceneNode,
  ScenePortRef,
  ScenePosition,
};

/* ------------------------------------------------------------------ */
/* The record                                                          */
/* ------------------------------------------------------------------ */

/* ------------------------------------------------------------------ */
/* Structural slices — what each pure function actually reads.         */
/* Typed minimally so the SAME functions run on a BlockScene, on a     */
/* React Flow store's nodes/edges, or on any host's records that speak */
/* the vocabulary. Matching the graph data types IS the adapter.       */
/* ------------------------------------------------------------------ */

/** `${nodeId}/${portId}` — the one shared spelling of "which port",
 *  everywhere: `wiredPorts`' set members, `sceneWires`' adapter output,
 *  and the view kit's own DOM resolution (`data-block-id` +
 *  `data-port-id`) all agree on it. */
export function portKey(nodeId: string, portId: string): string {
  return `${nodeId}/${portId}`;
}

/* ------------------------------------------------------------------ */
/* Wired state — the derivation wiring.ts used to own                  */
/* ------------------------------------------------------------------ */

/**
 * Every port named by at least one edge end, as `portKey`s. An edge end
 * with no handle wires the NODE, not any port, so it contributes nothing
 * here. Duplicate edges add nothing new — idempotence, not a bug.
 */
export function wiredPorts(scene: { edges: readonly SceneEdgeEnds[] }): Set<string> {
  const keys = new Set<string>();
  for (const edge of scene.edges) {
    if (edge.sourceHandle != null) keys.add(portKey(edge.source, edge.sourceHandle));
    if (edge.targetHandle != null) keys.add(portKey(edge.target, edge.targetHandle));
  }
  return keys;
}

/**
 * The edges that write INTO this port — its producers, in dataflow terms.
 * Total: an unknown port simply has none.
 */
export function producersOf<E extends SceneEdgeEnds>(scene: { edges: readonly E[] }, ref: ScenePortRef): E[] {
  return scene.edges.filter((edge) => edge.target === ref.nodeId && edge.targetHandle === ref.portId);
}

/** The edges that read FROM this port — its consumers. */
export function consumersOf<E extends SceneEdgeEnds>(scene: { edges: readonly E[] }, ref: ScenePortRef): E[] {
  return scene.edges.filter((edge) => edge.source === ref.nodeId && edge.sourceHandle === ref.portId);
}

/* ------------------------------------------------------------------ */
/* Order — the SPICE observation: a netlist has a evaluation order      */
/* ------------------------------------------------------------------ */

export interface SceneOrder {
  /** Node ids in dependency order: every edge's source before its target.
   *  Stable — scene order, refined only where an edge forces otherwise. */
  order: string[];
  /** Node ids that cannot be ordered: they sit ON a cycle or strictly
   *  BEHIND one (an acyclic node fed by a cycle is blocked too — its
   *  producers never settle). In scene order. */
  blocked: string[];
}

/** Adjacency + indegree over KNOWN nodes only — an edge naming a node id
 *  that isn't in the scene is ignored, not thrown on (total by policy:
 *  malformed input yields the honest smaller answer). `parentId` is
 *  deliberately NOT an edge: nesting is not dataflow. */
function dependencyGraph(scene: { nodes: readonly { id: string }[]; edges: readonly SceneEdgeEnds[] }): {
  ids: string[];
  successors: Map<string, string[]>;
  indegree: Map<string, number>;
} {
  const ids: string[] = [];
  const seen = new Set<string>();
  for (const node of scene.nodes) {
    // Duplicate ids: first occurrence wins, the rest are ignored — the
    // total-function answer to input the record's own contract forbids.
    if (!seen.has(node.id)) {
      seen.add(node.id);
      ids.push(node.id);
    }
  }
  const successors = new Map<string, string[]>(ids.map((id) => [id, []]));
  const indegree = new Map<string, number>(ids.map((id) => [id, 0]));
  for (const edge of scene.edges) {
    if (!seen.has(edge.source) || !seen.has(edge.target)) continue;
    successors.get(edge.source)!.push(edge.target);
    indegree.set(edge.target, indegree.get(edge.target)! + 1);
  }
  return { ids, successors, indegree };
}

/**
 * Kahn's algorithm, stable: among the ready nodes, always the earliest in
 * scene order — so an already-ordered scene comes back in its own order,
 * and reordering the input never reorders independent nodes surprisingly.
 * O(n² + e) by linear rescan; a scene is tens of blocks, not a genome
 * (the same size argument `portLane.ts` makes for its quadratic LCS).
 */
export function topologicalOrder(scene: { nodes: readonly { id: string }[]; edges: readonly SceneEdgeEnds[] }): SceneOrder {
  const { ids, successors, indegree } = dependencyGraph(scene);
  const placed = new Set<string>();
  const order: string[] = [];
  for (;;) {
    const ready = ids.find((id) => !placed.has(id) && indegree.get(id) === 0);
    if (ready === undefined) break;
    placed.add(ready);
    order.push(ready);
    for (const next of successors.get(ready)!) {
      indegree.set(next, indegree.get(next)! - 1);
    }
  }
  const blocked = ids.filter((id) => !placed.has(id));
  return { order, blocked };
}

/**
 * Longest-path depth from the sources: a node with no producers ranks 0,
 * every other node ranks one past its deepest producer. The number a
 * left-to-right auto-layout would use as its column. Blocked nodes (see
 * `topologicalOrder`) are absent from the map — no honest rank exists for
 * them.
 */
export function rank(scene: { nodes: readonly { id: string }[]; edges: readonly SceneEdgeEnds[] }): Map<string, number> {
  const { successors } = dependencyGraph(scene);
  const { order } = topologicalOrder(scene);
  const ranks = new Map<string, number>();
  for (const id of order) ranks.set(id, 0);
  for (const id of order) {
    const from = ranks.get(id)!;
    for (const next of successors.get(id)!) {
      // A successor that is blocked never entered `ranks`; leave it out
      // rather than inventing a depth for it.
      if (ranks.has(next)) ranks.set(next, Math.max(ranks.get(next)!, from + 1));
    }
  }
  return ranks;
}

/* ------------------------------------------------------------------ */
/* Cycles — the linter's real input                                    */
/* ------------------------------------------------------------------ */

/**
 * Every knot of mutual reachability: strongly connected components with
 * two or more nodes, plus self-loops, members in scene order. An SCC
 * rather than an enumerated loop path ON PURPOSE — one component can
 * contain many interleaved loops and "the" cycle path is not unique, so a
 * linter pointing at the whole knot tells the truth; a linter pointing at
 * one arbitrary path through it does not. Tarjan's algorithm, iterative
 * (an explicit stack, not recursion) so a pathological chain cannot blow
 * the call stack.
 */
export function findCycles(scene: { nodes: readonly { id: string }[]; edges: readonly SceneEdgeEnds[] }): string[][] {
  const { ids, successors } = dependencyGraph(scene);
  const indexOf = new Map<string, number>();
  const lowlink = new Map<string, number>();
  const onStack = new Set<string>();
  const stack: string[] = [];
  const components: string[][] = [];
  let counter = 0;

  const selfLoop = new Set<string>();
  for (const id of ids) {
    if (successors.get(id)!.includes(id)) selfLoop.add(id);
  }

  for (const root of ids) {
    if (indexOf.has(root)) continue;
    // Each frame: [node, index of the next successor to visit].
    const frames: [string, number][] = [[root, 0]];
    while (frames.length > 0) {
      const frame = frames[frames.length - 1];
      const [node, nextChild] = frame;
      if (nextChild === 0) {
        indexOf.set(node, counter);
        lowlink.set(node, counter);
        counter++;
        stack.push(node);
        onStack.add(node);
      }
      const children = successors.get(node)!;
      if (nextChild < children.length) {
        frame[1]++;
        const child = children[nextChild];
        if (!indexOf.has(child)) {
          frames.push([child, 0]);
        } else if (onStack.has(child)) {
          lowlink.set(node, Math.min(lowlink.get(node)!, indexOf.get(child)!));
        }
      } else {
        // Node finished: close its component if it is a root, then fold
        // its lowlink into its parent's.
        if (lowlink.get(node) === indexOf.get(node)) {
          const members: string[] = [];
          for (;;) {
            const popped = stack.pop()!;
            onStack.delete(popped);
            members.push(popped);
            if (popped === node) break;
          }
          if (members.length > 1 || selfLoop.has(node)) components.push(members);
        }
        frames.pop();
        if (frames.length > 0) {
          const parent = frames[frames.length - 1][0];
          lowlink.set(parent, Math.min(lowlink.get(parent)!, lowlink.get(node)!));
        }
      }
    }
  }

  // Scene order, inside each knot and between knots — deterministic for a
  // linter's report regardless of traversal accidents.
  const position = new Map(ids.map((id, i) => [id, i]));
  for (const members of components) members.sort((a, b) => position.get(a)! - position.get(b)!);
  components.sort((a, b) => position.get(a[0])! - position.get(b[0])!);
  return components;
}

/* ------------------------------------------------------------------ */
/* Duplicate edges — "multiple edges ending at the same port" lint      */
/* ------------------------------------------------------------------ */

/** Unordered, both handles included: `a/x → b/y` and `b/y → a/x` are the
 *  same pair — the visible fact is "N edges between these two ports", not
 *  which end either edge calls `source`. The SAME rule the view kit's
 *  duplicate fan uses (`wiring.ts`'s `fanWires`), so the lint and the
 *  drawing can never disagree about what counts as a duplicate. */
function unorderedPairKey(edge: SceneEdgeEnds): string {
  const a = portKey(edge.source, edge.sourceHandle ?? "");
  const b = portKey(edge.target, edge.targetHandle ?? "");
  return a <= b ? `${a}|${b}` : `${b}|${a}`;
}

/** Groups of 2+ edges sharing one unordered endpoint pair, groups in
 *  first-seen order, edges in scene order. Empty when every pair is
 *  unique — the honest nothing, not an error. */
export function duplicateEdges<E extends SceneEdgeEnds>(scene: { edges: readonly E[] }): E[][] {
  const groups = new Map<string, E[]>();
  for (const edge of scene.edges) {
    const key = unorderedPairKey(edge);
    const group = groups.get(key);
    if (group) group.push(edge);
    else groups.set(key, [edge]);
  }
  return [...groups.values()].filter((group) => group.length >= 2);
}

/* ------------------------------------------------------------------ */
/* Dangling edges — "an edge end that points at nothing" lint           */
/* ------------------------------------------------------------------ */

/** One unresolvable edge end. `reason` separates the two failures a
 *  linter reports differently: the whole node is gone, or the node is
 *  alive but no longer speaks that port. */
export interface DanglingEdgeEnd {
  edgeId: string;
  end: "source" | "target";
  /** The node id this end names — dead or alive. */
  nodeId: string;
  /** The handle this end names, when it names one. */
  portId?: string;
  reason: "missing-node" | "missing-port";
}

/**
 * Every edge end that does not resolve to a live node — and, when the
 * caller can state a node's port vocabulary, to a live PORT on it. One
 * function serves both of Zach's cases (2026-09-17): during interaction
 * a host may permit dangling deliberately (`deleteNode`'s `"dangle"` /
 * `"park"` policies in linking.ts) and this is what keeps that safe
 * rather than silently corrupting; at load time nobody chose anything,
 * so a dangling un-parked end means the document is wrong. Same
 * question either way — only the response differs, and the response is
 * the host's.
 *
 * `portsOf` is optional and per-node total: omitted, only node
 * existence is checked; returning `undefined` for a node means "this
 * node's vocabulary is unknown", so no port judgement is made for it.
 * The port check exists because port identity is namespaced to the node
 * (`portKey`): a node can survive while one of its ports dies, and a
 * node-only check never sees that. An end with no handle wires the
 * NODE, so it can only dangle by `missing-node`.
 *
 * Total: a healthy scene yields `[]`, malformed input yields the honest
 * report, never a throw. Scene order, source end before target —
 * deterministic for a linter.
 */
export function findDanglingEdges<E extends SceneEdgeEnds & { id: string }>(
  scene: { nodes: readonly { id: string }[]; edges: readonly E[] },
  portsOf?: (nodeId: string) => readonly string[] | undefined,
): DanglingEdgeEnd[] {
  const known = new Set(scene.nodes.map((node) => node.id));
  const report: DanglingEdgeEnd[] = [];
  for (const edge of scene.edges) {
    for (const end of ["source", "target"] as const) {
      const nodeId = edge[end];
      const handle = end === "source" ? edge.sourceHandle : edge.targetHandle;
      if (!known.has(nodeId)) {
        report.push({ edgeId: edge.id, end, nodeId, ...(handle != null ? { portId: handle } : {}), reason: "missing-node" });
        continue;
      }
      if (handle == null || !portsOf) continue;
      const vocabulary = portsOf(nodeId);
      if (vocabulary !== undefined && !vocabulary.includes(handle)) {
        report.push({ edgeId: edge.id, end, nodeId, portId: handle, reason: "missing-port" });
      }
    }
  }
  return report;
}

/* ------------------------------------------------------------------ */
/* Identity under duplication                                          */
/* ------------------------------------------------------------------ */

/**
 * An independent copy of one node. The id is minted by the CALLER —
 * host-owned id minting, the same D9 rule `portLane.ts`'s `mintItem`
 * already established: this module never invents an id. Everything else
 * copies verbatim: `data` (so the copy keeps its `name` — two nodes may
 * share a name; they may never share an id), `position` (the caller
 * offsets it if it wants a visible ghost), `parentId` (the copy lives
 * where the original lives), and `definitionId` (a copy of a linked copy
 * is another linked copy of the SAME definition — copying never launders
 * the link away, and never adds one).
 *
 * Edges are NOT copied: an edge names two specific ports on two specific
 * nodes, and the copy's ports have no wires yet — duplicating a node must
 * not silently multiply connections (React Flow's own copy behaviour).
 * Children are not copied either — this is one node, not a subtree.
 *
 * Total + referentially honest: an unknown `nodeId` returns the SAME
 * scene object (not a structurally-equal copy), the no-op contract
 * `reconcilePortLane` set for this codebase.
 */
export function duplicateNode<NodeData extends SceneData, EdgeData extends SceneData>(
  scene: BlockScene<NodeData, EdgeData>,
  nodeId: string,
  mintId: () => string,
): BlockScene<NodeData, EdgeData> {
  const source = scene.nodes.find((node) => node.id === nodeId);
  if (!source) return scene;
  return { ...scene, nodes: [...scene.nodes, { ...source, id: mintId() }] };
}

/**
 * A LINKED copy: same as `duplicateNode`, except the copy is another
 * OCCURRENCE of the source's definition. If the source already belongs
 * to a group, the copy shares its `definitionId`; if not, a group id is
 * minted (the second `mintId` call) and stamped on BOTH — the source
 * becomes the group's first occurrence, not its root: a definition has
 * no root node, only members, so deleting any one occurrence (the
 * original included) never orphans the rest. "Every occurrence of this
 * definition" stays one equality test (`linkedCopies`), never a walk.
 */
export function linkedCopy<NodeData extends SceneData, EdgeData extends SceneData>(
  scene: BlockScene<NodeData, EdgeData>,
  nodeId: string,
  mintId: () => string,
): BlockScene<NodeData, EdgeData> {
  const source = scene.nodes.find((node) => node.id === nodeId);
  if (!source) return scene;
  const copyId = mintId();
  const definitionId = source.definitionId ?? mintId();
  const copy = { ...source, id: copyId, definitionId };
  const nodes = source.definitionId
    ? [...scene.nodes, copy]
    : [...scene.nodes.map((node) => (node === source ? { ...node, definitionId } : node)), copy];
  return { ...scene, nodes };
}

/** Every occurrence of one definition group, in scene order — the
 *  original among them: occurrences are peers, none is privileged. */
export function linkedCopies<NodeData extends SceneData>(
  scene: { nodes: readonly SceneNode<NodeData>[] },
  definitionId: string,
): SceneNode<NodeData>[] {
  return scene.nodes.filter((node) => node.definitionId === definitionId);
}

/* ------------------------------------------------------------------ */
/* Nesting queries                                                     */
/* ------------------------------------------------------------------ */

/** The members of one node, in scene order — the read side of
 *  `parentId`. */
export function childrenOf<NodeData extends SceneData>(
  scene: { nodes: readonly SceneNode<NodeData>[] },
  nodeId: string,
): SceneNode<NodeData>[] {
  return scene.nodes.filter((node) => node.parentId === nodeId);
}

// src/scene/sceneWires.ts — the host adapter: scene in, view-kit props
// out. This module is ALLOWED to know both vocabularies (the same licence
// the repo's engine adapters have — "an adapter may import the core and
// its own engine"); the two kits it bridges never import each other. The
// view kit's `WireLayer` keeps its own `Wire` prop type and no component
// ever sees a scene; a host calls these functions and passes the result
// down as ordinary props. That one-way flow is the separation working.
import type { PortEdgeItem } from "../components/portEdge";
import type { TraceMarkerEnd, TraceRouting, TraceVariant } from "../components/trace.layout";
import type { Wire } from "../components/wiring";
import { ancestorsOf } from "./region";
import { portKey, type SceneData, type SceneEdge, type SceneNode } from "./scene";

/**
 * Per-edge view styling, riding in `SceneEdge.data` — a `type` alias so it
 * satisfies `SceneData`'s implicit-index-signature requirement. The SCENE
 * does not know these fields exist (they are `data` to it); only this
 * adapter reads them. A host that styles differently writes its own data
 * type and its own adapter.
 */
export type WireStyleData = {
  /** Default `"data"` — `wiring.ts`'s own rule, unchanged. */
  variant?: TraceVariant;
  routing?: TraceRouting;
  markerEnd?: TraceMarkerEnd;
  color?: string;
  /** Pill text riding the wire (`Wire.badge`). Authoring it is optional:
   *  a `delayed` edge that names none still gets one — see `sceneWires`. */
  badge?: string;
};

/** What `sceneWires` derives `through` from. `nodes` is OPTIONAL so every
 *  caller that only ever had edges (`sceneWires({ edges })`, the async
 *  gallery) keeps compiling and keeps getting `through: []` — a wire with
 *  no declared containers is exactly a wire that may enter none of them,
 *  which is the right answer for a flat bench. */
export interface SceneWiresInput<N extends SceneData = SceneData> {
  nodes?: readonly SceneNode<N>[];
  edges: readonly SceneEdge<WireStyleData>[];
}

/**
 * `SceneEdge[]` → `Wire[]`, one to one, order preserved. `source` becomes
 * the `from` block, `sourceHandle` the `from` port (`Wire`'s arrowhead
 * rule — points AT `to` — maps onto React Flow's own source→target
 * direction unchanged). An end with NO handle maps to `portId: ""`, which
 * no rendered dot ever carries — `WireLayer` then reports that wire in
 * `data-unresolved-wires`, its established "skipped, not guessed at"
 * channel, rather than this adapter inventing an anchor.
 */
export function sceneWires<N extends SceneData>(scene: SceneWiresInput<N>): Wire[] {
  const containment = { nodes: scene.nodes ?? [] };
  return scene.edges.map((edge) => ({
    id: edge.id,
    from: { blockId: edge.source, portId: edge.sourceHandle ?? "" },
    to: { blockId: edge.target, portId: edge.targetHandle ?? "" },
    variant: edge.data?.variant,
    // WHY this stays `undefined` when nobody authored one, instead of
    // filling in `DEFAULT_TRACE_ROUTING` here: the adapter's job is to say
    // what the SCENE says, and the scene says nothing. Defaulting here would
    // make every derived `Wire` look explicitly routed, so a host could no
    // longer tell "the author chose elbow" from "the author chose nothing" —
    // and the day the default changes again, boards would silently keep
    // whatever this function baked in. The default is applied once, at
    // paint, by `WireLayer` / `Trace` / the tldraw overlay.
    routing: edge.data?.routing,
    markerEnd: edge.data?.markerEnd,
    color: edge.data?.color,
    // The containers this cable is genuinely INSIDE: the `parentId` chain
    // of both ends, deduped, nothing else. `ancestorsOf` is the scene kit's
    // one parent walk (cycle-safe, containment-only, never a definition
    // group) — restating it here is how two readings of "which region am I
    // in" start to disagree.
    through: throughOf(containment, edge.source, edge.target),
    // WHY a `delayed` cable gets "z⁻¹" without anyone authoring it (plan Q7,
    // "always draw the pill"): the delay is the whole meaning of a carried
    // value, and a dotted line alone does not say WHAT is delayed by how
    // much. An authored `badge` always wins, so "z⁻¹ = estimate()" — the seed
    // spelled out — is a plain data override, not a special case.
    badge: edge.data?.badge ?? (edge.data?.variant === "delayed" ? "z⁻¹" : undefined),
  }));
}

/** Both ends' ancestor chains, deduped, source's first. A self-loop names
 *  its one chain once — the same "excluded once" the keep-out set gives an
 *  endpoint block. */
function throughOf<N extends SceneData>(
  scene: { nodes: readonly SceneNode<N>[] },
  source: string,
  target: string,
): string[] {
  if (scene.nodes.length === 0) return [];
  return [...new Set([...ancestorsOf(scene, source), ...ancestorsOf(scene, target)])];
}

/**
 * `items`, with `state: "wired"` forced onto every member the scene's
 * edges name, and left alone otherwise — a fixture-authored `valueSet` or
 * `received` survives on an unwired port, but wired always wins when
 * wired. Moved here verbatim from `wiring.ts` (it is scene→view
 * derivation, not paint): `wired` is `wiredPorts(scene)`, whose members
 * are `portKey(nodeId, portId)` — the one shared spelling of "which
 * port".
 */
export function withWiredState(items: readonly PortEdgeItem[], nodeId: string, wired: ReadonlySet<string>): PortEdgeItem[] {
  return items.map((item) => (wired.has(portKey(nodeId, item.id)) ? { ...item, state: "wired" } : item));
}

